namespace SESS.NexaERP.Infrastructure.Persistence.Migrations;

/// <summary>Frozen Correction 19 target-local command, purge and export ledgers.</summary>
internal static class Rev869BCommandContextSql
{
    internal const string Install = """
        DO $roles$ DECLARE r text; expected_login boolean; BEGIN
          FOR r,expected_login IN SELECT * FROM (VALUES
            ('nexa_rev869b_security_owner',false),('nexa_rev869b_app_runtime',true),('nexa_rev869b_command_audit',true),
            ('nexa_rev869b_management_writer',true),('nexa_rev869b_purge_worker',true),('nexa_rev869b_purge_audit',true),
            ('nexa_rev869b_export_service',true),('nexa_rev869b_target_verifier',true)) AS expected(name,can_login) LOOP
            IF NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname=r AND rolcanlogin=expected_login AND NOT rolinherit AND NOT rolsuper AND NOT rolcreatedb AND NOT rolcreaterole AND NOT rolreplication AND NOT rolbypassrls AND rolconnlimit=-1 AND rolvaliduntil IS NULL) THEN RAISE EXCEPTION 'Missing or noncanonical capability-free frozen role %',r; END IF;
          END LOOP;
          IF EXISTS(SELECT 1 FROM pg_auth_members m JOIN pg_roles a ON a.oid=m.roleid JOIN pg_roles b ON b.oid=m.member WHERE (a.rolname LIKE 'nexa_rev869b_%' OR b.rolname LIKE 'nexa_rev869b_%') AND NOT (a.rolname='nexa_rev869b_security_owner' AND b.rolname='nexa_rev869b_lifecycle_administrator')) OR NOT EXISTS(SELECT 1 FROM pg_auth_members m JOIN pg_roles a ON a.oid=m.roleid JOIN pg_roles b ON b.oid=m.member WHERE a.rolname='nexa_rev869b_security_owner' AND b.rolname='nexa_rev869b_lifecycle_administrator') THEN RAISE EXCEPTION 'REV869B roles require only the security-owner grant to the lifecycle administrator'; END IF;
        END $roles$;
        CREATE TABLE nexa.rev869b_command_requests(
          "CommandId" uuid PRIMARY KEY,"OrganizationId" text NOT NULL,"Operation" text NOT NULL,"IdempotencyKeySha256" bytea NOT NULL CHECK(octet_length("IdempotencyKeySha256")=32),"RequestSha256" bytea NOT NULL CHECK(octet_length("RequestSha256")=32),
          "ActorEmployeeId" uuid NOT NULL,"IdentityIssuer" text NOT NULL,"IdentitySubject" text NOT NULL,"ActorRole" text NOT NULL,"RegisteredAt" timestamptz NOT NULL DEFAULT clock_timestamp(),"RegisteredBy" name NOT NULL DEFAULT session_user,
          UNIQUE("OrganizationId","Operation","IdempotencyKeySha256"));
        CREATE TABLE nexa.rev869b_command_attempts(
          "AttemptId" uuid PRIMARY KEY,"CommandId" uuid NOT NULL REFERENCES nexa.rev869b_command_requests("CommandId"),"AttemptOrdinal" integer NOT NULL CHECK("AttemptOrdinal">0),"ExecutionInstanceId" uuid NOT NULL,
          "ServiceInstanceSha256" bytea NOT NULL CHECK(octet_length("ServiceInstanceSha256")=32),"OwnershipLeaseSha256" bytea NOT NULL CHECK(octet_length("OwnershipLeaseSha256")=32),"RuntimePrincipal" name NOT NULL,
          "TargetBackendPid" integer NOT NULL,"TargetTransactionId" bigint NOT NULL,"IsActive" boolean NOT NULL DEFAULT true,"StartedAt" timestamptz NOT NULL DEFAULT clock_timestamp(),"StartedBy" name NOT NULL DEFAULT session_user,UNIQUE("CommandId","AttemptOrdinal"));
        CREATE UNIQUE INDEX "UX_rev869b_one_active_command_attempt" ON nexa.rev869b_command_attempts("CommandId") WHERE "IsActive";
        CREATE TABLE nexa.rev869b_command_contexts(
          "ContextToken" uuid PRIMARY KEY,"AttemptId" uuid NOT NULL UNIQUE REFERENCES nexa.rev869b_command_attempts("AttemptId"),"OrganizationId" text NOT NULL,"BackendPid" integer NOT NULL,"TransactionId" bigint NOT NULL,"RuntimePrincipal" name NOT NULL,
          "SlotSha256" bytea NOT NULL CHECK(octet_length("SlotSha256")=32),"Slots" jsonb NOT NULL CHECK(jsonb_typeof("Slots")='array' AND jsonb_array_length("Slots")>0),"SlotCount" integer NOT NULL CHECK("SlotCount">0),"OpenedAt" timestamptz NOT NULL DEFAULT transaction_timestamp());
        CREATE INDEX "IX_rev869b_command_contexts_organization_opened_token" ON nexa.rev869b_command_contexts("OrganizationId","OpenedAt","ContextToken") INCLUDE("AttemptId");
        CREATE TABLE nexa.rev869b_command_claims(
          "ClaimId" bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,"ContextToken" uuid NOT NULL REFERENCES nexa.rev869b_command_contexts("ContextToken"),"ClaimKind" text NOT NULL,"HistoryId" uuid NOT NULL,"EntityType" text NOT NULL,"EntityId" uuid NOT NULL,
          "Operation" text NOT NULL,"ParentVersion" bigint NOT NULL,"FromStatus" text NULL,"ToStatus" text NOT NULL,"Correlation" text NOT NULL,"RemarksSha256" bytea NOT NULL CHECK(octet_length("RemarksSha256")=32),UNIQUE("ContextToken","ClaimKind","HistoryId"));
        CREATE TABLE nexa.rev869b_command_attempt_outcomes(
          "OutcomeId" uuid PRIMARY KEY,"AttemptId" uuid NOT NULL UNIQUE REFERENCES nexa.rev869b_command_attempts("AttemptId"),"TerminalState" text NOT NULL CHECK("TerminalState" IN ('Committed','Rejected','RolledBack','Abandoned')),
          "Category" text NULL,"BusinessSha256" bytea NULL,"OccurredAt" timestamptz NOT NULL DEFAULT clock_timestamp(),"RecordedBy" name NOT NULL DEFAULT session_user,
          CHECK(("TerminalState"='Committed' AND octet_length("BusinessSha256")=32 AND "Category" IS NULL) OR ("TerminalState"<>'Committed' AND "BusinessSha256" IS NULL AND length("Category") BETWEEN 1 AND 100)));
        CREATE TABLE nexa.rev869b_command_receipts(
          "ReceiptId" uuid PRIMARY KEY,"AttemptId" uuid NOT NULL UNIQUE REFERENCES nexa.rev869b_command_attempts("AttemptId"),"CommandId" uuid NOT NULL UNIQUE REFERENCES nexa.rev869b_command_requests("CommandId"),
          "BusinessSha256" bytea NOT NULL CHECK(octet_length("BusinessSha256")=32),"ResponseJson" jsonb NOT NULL,"CommittedAt" timestamptz NOT NULL DEFAULT transaction_timestamp());
        CREATE TABLE nexa.rev869b_target_instance_identity(
          "IdentityId" boolean PRIMARY KEY DEFAULT true CHECK("IdentityId"),"InstanceId" uuid NOT NULL UNIQUE,"LeaseId" uuid NOT NULL UNIQUE,
          "DatabaseName" name NOT NULL,"InstanceSha256" bytea NOT NULL UNIQUE CHECK(octet_length("InstanceSha256")=32),
          "CreatedAt" timestamptz NOT NULL DEFAULT clock_timestamp(),CHECK("DatabaseName"=current_database()));
        WITH identity AS (SELECT gen_random_uuid() AS id)
        INSERT INTO nexa.rev869b_target_instance_identity("IdentityId","InstanceId","LeaseId","DatabaseName","InstanceSha256")
        SELECT true,id,current_setting('nexa.rev869b_lease_id')::uuid,current_database(),digest(convert_to(current_database()||':'||id::text,'UTF8'),'sha256') FROM identity
        WHERE current_setting('nexa.rev869b_lease_id')::uuid<>'00000000-0000-0000-0000-000000000000'::uuid;
        CREATE TABLE nexa.rev869b_purge_authorizations(
          "AuthorizationId" uuid PRIMARY KEY,"ManagementDecisionId" uuid NOT NULL UNIQUE,"RootAuthorizationId" uuid NOT NULL,"PriorAttemptId" uuid NULL,"AuthorizedBatchId" uuid NOT NULL UNIQUE,
          "TargetInstanceSha256" bytea NOT NULL CHECK(octet_length("TargetInstanceSha256")=32),"Operation" text NOT NULL CHECK("Operation"='CommandContextRetentionPurge'),
          "Scope" text NOT NULL,"Cutoff" timestamptz NOT NULL,"MaximumRows" integer NOT NULL CHECK("MaximumRows" BETWEEN 1 AND 1000),"RetryOrdinal" integer NOT NULL CHECK("RetryOrdinal">=0),
          "PriorTerminalOutcome" text NULL CHECK("PriorTerminalOutcome" IS NULL OR "PriorTerminalOutcome" IN ('Failed','Interrupted')),"PriorEvidenceSha256" bytea NULL CHECK("PriorEvidenceSha256" IS NULL OR octet_length("PriorEvidenceSha256")=32),
          "NonceSha256" bytea NOT NULL CHECK(octet_length("NonceSha256")=32),"ExpiresAt" timestamptz NOT NULL,"State" text NOT NULL DEFAULT 'Approved' CHECK("State" IN ('Approved','Expired','ZeroRows','Started','Succeeded','Failed','Interrupted')),
          "IssuedAt" timestamptz NOT NULL DEFAULT clock_timestamp(),"IssuedBy" name NOT NULL DEFAULT session_user,CHECK("ExpiresAt">"IssuedAt" AND "ExpiresAt"<="IssuedAt"+interval '15 minutes'),
          CHECK(("PriorAttemptId" IS NULL AND "RootAuthorizationId"="AuthorizationId" AND "RetryOrdinal"=0 AND "PriorTerminalOutcome" IS NULL AND "PriorEvidenceSha256" IS NULL) OR ("PriorAttemptId" IS NOT NULL AND "RetryOrdinal">0 AND "PriorTerminalOutcome" IS NOT NULL AND octet_length("PriorEvidenceSha256")=32)));
        CREATE TABLE nexa.rev869b_purge_attempts(
          "PurgeAttemptId" uuid PRIMARY KEY,"AuthorizationId" uuid NOT NULL UNIQUE REFERENCES nexa.rev869b_purge_authorizations("AuthorizationId"),"CandidateCount" integer NOT NULL,"CandidateSha256" bytea NOT NULL CHECK(octet_length("CandidateSha256")=32),
          "State" text NOT NULL CHECK("State" IN ('ZeroRows','Started','Succeeded','Failed','Interrupted')),"StartedAt" timestamptz NOT NULL DEFAULT clock_timestamp(),"TerminalAt" timestamptz NULL,"FailureCategory" text NULL);
        ALTER TABLE nexa.rev869b_purge_authorizations ADD CONSTRAINT "FK_rev869b_purge_authorizations_prior_attempt" FOREIGN KEY("PriorAttemptId") REFERENCES nexa.rev869b_purge_attempts("PurgeAttemptId");
        ALTER TABLE nexa.rev869b_purge_authorizations ADD CONSTRAINT "FK_rev869b_purge_authorizations_root" FOREIGN KEY("RootAuthorizationId") REFERENCES nexa.rev869b_purge_authorizations("AuthorizationId");
        CREATE UNIQUE INDEX "UX_rev869b_purge_authorizations_prior_attempt" ON nexa.rev869b_purge_authorizations("PriorAttemptId") WHERE "PriorAttemptId" IS NOT NULL AND "State"<>'Expired';
        CREATE TABLE nexa.rev869b_purge_candidates("PurgeAttemptId" uuid NOT NULL REFERENCES nexa.rev869b_purge_attempts("PurgeAttemptId"),"LedgerName" text NOT NULL,"RowId" uuid NOT NULL,PRIMARY KEY("PurgeAttemptId","LedgerName","RowId"));
        CREATE TABLE nexa.rev869b_purge_events("EventId" bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,"PurgeAttemptId" uuid NOT NULL,"State" text NOT NULL,"EvidenceSha256" bytea NOT NULL CHECK(octet_length("EvidenceSha256")=32),"OccurredAt" timestamptz NOT NULL DEFAULT clock_timestamp(),"Principal" name NOT NULL DEFAULT session_user,UNIQUE("PurgeAttemptId","State"));
        CREATE TABLE nexa.rev869b_export_authorizations(
          "AuthorizationId" uuid PRIMARY KEY,"ManagementDecisionId" uuid NOT NULL UNIQUE,"OrganizationId" text NOT NULL,"Fields" text[] NOT NULL,"MaximumRows" integer NOT NULL CHECK("MaximumRows" BETWEEN 1 AND 1000),"AsOf" timestamptz NOT NULL,"ExpiresAt" timestamptz NOT NULL,
          "State" text NOT NULL DEFAULT 'Approved' CHECK("State" IN ('Approved','Prepared','Expired')),"IssuedAt" timestamptz NOT NULL DEFAULT clock_timestamp(),"IssuedBy" name NOT NULL DEFAULT session_user,CHECK("ExpiresAt">"IssuedAt" AND "ExpiresAt"<="IssuedAt"+interval '15 minutes'));
        CREATE TABLE nexa.rev869b_export_batches(
          "BatchId" uuid PRIMARY KEY,"AuthorizationId" uuid NOT NULL UNIQUE REFERENCES nexa.rev869b_export_authorizations("AuthorizationId"),"ManagementDecisionId" uuid NOT NULL UNIQUE,"OrganizationId" text NOT NULL,"Fields" text[] NOT NULL,"MaximumRows" integer NOT NULL CHECK("MaximumRows" BETWEEN 1 AND 1000),"AsOf" timestamptz NOT NULL,"ExpiresAt" timestamptz NOT NULL,
          "RowCount" integer NOT NULL,"BatchSha256" bytea NOT NULL CHECK(octet_length("BatchSha256")=32),"PreparedAt" timestamptz NOT NULL DEFAULT clock_timestamp(),CHECK("ExpiresAt">"PreparedAt" AND "ExpiresAt"<="PreparedAt"+interval '15 minutes'));
        CREATE TABLE nexa.rev869b_export_batch_rows("BatchId" uuid NOT NULL REFERENCES nexa.rev869b_export_batches("BatchId"),"Ordinal" integer NOT NULL,"Payload" jsonb NOT NULL,"RowSha256" bytea NOT NULL CHECK(octet_length("RowSha256")=32),PRIMARY KEY("BatchId","Ordinal"));
        CREATE TABLE nexa.rev869b_export_releases("ReleaseId" uuid PRIMARY KEY,"BatchId" uuid NOT NULL REFERENCES nexa.rev869b_export_batches("BatchId"),"State" text NOT NULL CHECK("State" IN ('ReleaseStarted','Delivered','Failed','Interrupted')),"StartedAt" timestamptz NOT NULL DEFAULT clock_timestamp(),"TerminalAt" timestamptz NULL,"OutcomeCategory" text NULL);
        CREATE UNIQUE INDEX "UX_rev869b_one_active_export_release" ON nexa.rev869b_export_releases("BatchId") WHERE "State"='ReleaseStarted';
        CREATE TABLE nexa.rev869b_target_catalogue_manifest("ManifestId" boolean PRIMARY KEY DEFAULT true CHECK("ManifestId"),"CatalogueSha256" text NULL CHECK("CatalogueSha256" IS NULL OR "CatalogueSha256"~'^[0-9a-f]{64}$'));
        INSERT INTO nexa.rev869b_target_catalogue_manifest VALUES(true,NULL);

        CREATE FUNCTION nexa.rev869b_deny_ledger_mutation() RETURNS trigger LANGUAGE plpgsql AS $f$ BEGIN RAISE EXCEPTION 'REV869B durable ledger is append-only'; END $f$;
        CREATE TRIGGER "TR_rev869b_command_outcomes_immutable" BEFORE UPDATE OR DELETE ON nexa.rev869b_command_attempt_outcomes FOR EACH ROW EXECUTE FUNCTION nexa.rev869b_deny_ledger_mutation();
        CREATE TRIGGER "TR_rev869b_command_receipts_immutable" BEFORE UPDATE OR DELETE ON nexa.rev869b_command_receipts FOR EACH ROW EXECUTE FUNCTION nexa.rev869b_deny_ledger_mutation();
        CREATE TRIGGER "TR_rev869b_target_instance_identity_immutable" BEFORE UPDATE OR DELETE ON nexa.rev869b_target_instance_identity FOR EACH ROW EXECUTE FUNCTION nexa.rev869b_deny_ledger_mutation();
        CREATE TRIGGER "TR_rev869b_purge_authorizations_no_delete" BEFORE DELETE ON nexa.rev869b_purge_authorizations FOR EACH ROW EXECUTE FUNCTION nexa.rev869b_deny_ledger_mutation();
        CREATE TRIGGER "TR_rev869b_purge_attempts_no_delete" BEFORE DELETE ON nexa.rev869b_purge_attempts FOR EACH ROW EXECUTE FUNCTION nexa.rev869b_deny_ledger_mutation();
        CREATE TRIGGER "TR_rev869b_purge_events_immutable" BEFORE UPDATE OR DELETE ON nexa.rev869b_purge_events FOR EACH ROW EXECUTE FUNCTION nexa.rev869b_deny_ledger_mutation();
        CREATE TRIGGER "TR_rev869b_export_rows_immutable" BEFORE UPDATE OR DELETE ON nexa.rev869b_export_batch_rows FOR EACH ROW EXECUTE FUNCTION nexa.rev869b_deny_ledger_mutation();

        CREATE FUNCTION nexa.rev869b_register_command_request(organization text,operation text,idempotency_sha bytea,request_sha bytea,actor_employee uuid,identity_issuer text,identity_subject text,actor_role text)
        RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,nexa AS $f$ DECLARE command_id uuid; existing nexa.rev869b_command_requests%ROWTYPE; BEGIN
          IF session_user<>'nexa_rev869b_command_audit' OR organization='' OR operation='' OR octet_length(idempotency_sha)<>32 OR octet_length(request_sha)<>32 THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Exact command request required'; END IF;
          SELECT * INTO existing FROM nexa.rev869b_command_requests r WHERE r."OrganizationId"=organization AND r."Operation"=operation AND r."IdempotencyKeySha256"=idempotency_sha FOR UPDATE;
          IF FOUND THEN IF existing."RequestSha256"<>request_sha OR existing."ActorEmployeeId"<>actor_employee OR existing."IdentityIssuer"<>identity_issuer OR existing."IdentitySubject"<>identity_subject OR existing."ActorRole"<>actor_role THEN RAISE EXCEPTION USING ERRCODE='23505',CONSTRAINT='rev869b_command_request_replay_mismatch',MESSAGE='Idempotency replay mismatch'; END IF; RETURN existing."CommandId"; END IF;
          command_id:=gen_random_uuid(); INSERT INTO nexa.rev869b_command_requests VALUES(command_id,organization,operation,idempotency_sha,request_sha,actor_employee,identity_issuer,identity_subject,actor_role,clock_timestamp(),session_user); RETURN command_id;
        END $f$;
        CREATE FUNCTION nexa.rev869b_start_command_attempt(command_id uuid,execution_instance uuid,service_sha bytea,ownership_sha bytea,runtime_principal name,backend_pid integer,transaction_id bigint)
        RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,nexa AS $f$ DECLARE attempt_id uuid:=gen_random_uuid(); ordinal integer; active nexa.rev869b_command_attempts%ROWTYPE; BEGIN
          IF session_user<>'nexa_rev869b_command_audit' OR octet_length(service_sha)<>32 OR octet_length(ownership_sha)<>32 OR runtime_principal<>'nexa_rev869b_app_runtime' THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Exact command attempt required'; END IF;
          PERFORM 1 FROM nexa.rev869b_command_requests WHERE "CommandId"=command_id FOR UPDATE; IF EXISTS(SELECT 1 FROM nexa.rev869b_command_receipts WHERE "CommandId"=command_id) THEN RETURN NULL; END IF;
          SELECT * INTO active FROM nexa.rev869b_command_attempts WHERE "CommandId"=command_id AND "IsActive"; IF FOUND THEN IF active."ExecutionInstanceId"=execution_instance AND active."ServiceInstanceSha256"=service_sha AND active."OwnershipLeaseSha256"=ownership_sha AND active."RuntimePrincipal"=runtime_principal AND active."TargetBackendPid"=backend_pid AND active."TargetTransactionId"=transaction_id THEN RETURN active."AttemptId"; END IF; RAISE EXCEPTION USING ERRCODE='40001',CONSTRAINT='rev869b_command_attempt_active',MESSAGE='Another bound command attempt is active'; END IF;
          SELECT coalesce(max("AttemptOrdinal"),0)+1 INTO ordinal FROM nexa.rev869b_command_attempts WHERE "CommandId"=command_id; INSERT INTO nexa.rev869b_command_attempts VALUES(attempt_id,command_id,ordinal,execution_instance,service_sha,ownership_sha,runtime_principal,backend_pid,transaction_id,true,clock_timestamp(),session_user); RETURN attempt_id;
        END $f$;
        CREATE FUNCTION nexa.rev869b_open_command_attempt(attempt_id uuid,actor_employee uuid,identity_issuer text,identity_subject text,actor_role text,organization text,slot_sha bytea,slots jsonb)
        RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,nexa AS $f$ DECLARE token uuid:=gen_random_uuid(); BEGIN
          IF session_user<>'nexa_rev869b_app_runtime' OR jsonb_typeof(slots)<>'array' OR jsonb_array_length(slots)=0 OR octet_length(slot_sha)<>32 THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Exact runtime context required'; END IF;
          IF NOT EXISTS(SELECT 1 FROM nexa.rev869b_command_attempts a JOIN nexa.rev869b_command_requests r ON r."CommandId"=a."CommandId" WHERE a."AttemptId"=attempt_id AND a."IsActive" AND a."RuntimePrincipal"=session_user AND a."TargetBackendPid"=pg_backend_pid() AND a."TargetTransactionId"=txid_current() AND r."ActorEmployeeId"=actor_employee AND r."IdentityIssuer"=identity_issuer AND r."IdentitySubject"=identity_subject AND r."ActorRole"=actor_role AND r."OrganizationId"=organization) THEN RAISE EXCEPTION USING ERRCODE='42501',CONSTRAINT='rev869b_attempt_binding',MESSAGE='Attempt binding mismatch'; END IF;
          PERFORM pg_advisory_xact_lock(hashtextextended(attempt_id::text,86923));
          PERFORM pg_advisory_xact_lock(hashtextextended(attempt_id::text,86924));

          SELECT "ContextToken" INTO token FROM nexa.rev869b_command_contexts WHERE "AttemptId"=attempt_id AND "BackendPid"=pg_backend_pid() AND "TransactionId"=txid_current();
          IF FOUND THEN
            UPDATE nexa.rev869b_command_contexts SET "SlotSha256"=digest("SlotSha256"||slot_sha,'sha256'),"Slots"="Slots"||slots,"SlotCount"="SlotCount"+jsonb_array_length(slots) WHERE "ContextToken"=token;
          ELSE
            token:=gen_random_uuid(); INSERT INTO nexa.rev869b_command_contexts VALUES(token,attempt_id,organization,pg_backend_pid(),txid_current(),session_user,slot_sha,slots,jsonb_array_length(slots),transaction_timestamp());
          END IF;
          PERFORM set_config('nexa.rev869b_command_token',token::text,true); PERFORM set_config('nexa.rev869b_actor_employee_id',actor_employee::text,true); PERFORM set_config('nexa.rev869b_identity_issuer',identity_issuer,true); PERFORM set_config('nexa.rev869b_identity_subject',identity_subject,true); PERFORM set_config('nexa.rev869b_actor_login',identity_subject,true); PERFORM set_config('nexa.rev869b_actor_role',actor_role,true); PERFORM set_config('nexa.rev869b_organization',organization,true); RETURN token;
        END $f$;
        CREATE FUNCTION nexa.rev869b_command_context_valid(organization text,actor_employee uuid,identity_issuer text,identity_subject text,actor_role text)
        RETURNS boolean LANGUAGE sql SECURITY DEFINER STABLE SET search_path=pg_catalog,nexa AS $f$ SELECT count(*)=1 FROM nexa.rev869b_command_contexts c JOIN nexa.rev869b_command_attempts a ON a."AttemptId"=c."AttemptId" JOIN nexa.rev869b_command_requests r ON r."CommandId"=a."CommandId" WHERE c."ContextToken"=nullif(current_setting('nexa.rev869b_command_token',true),'')::uuid AND c."BackendPid"=pg_backend_pid() AND c."TransactionId"=txid_current() AND c."RuntimePrincipal"=session_user AND a."IsActive" AND r."OrganizationId"=$1 AND r."ActorEmployeeId"=$2 AND r."IdentityIssuer"=$3 AND r."IdentitySubject"=$4 AND r."ActorRole"=$5 $f$;
        CREATE FUNCTION nexa.rev869b_claim_command_context(claim_kind text,history_id uuid,entity_type text,entity_id uuid,operation text,parent_version bigint,from_status text,to_status text,correlation text,remarks text)
        RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,nexa AS $f$ DECLARE token uuid:=nullif(current_setting('nexa.rev869b_command_token',true),'')::uuid; expected jsonb; BEGIN
          SELECT value INTO expected FROM nexa.rev869b_command_contexts c,jsonb_array_elements(c."Slots") value WHERE c."ContextToken"=token AND value->>'claimKind'=claim_kind AND (value->>'historyId')::uuid=history_id AND value->>'entityType'=entity_type AND (value->>'entityId')::uuid=entity_id AND value->>'operation'=operation AND (value->>'parentVersion')::bigint=parent_version AND value->>'toStatus'=to_status AND value->>'correlation'=correlation;
          IF expected IS NULL OR (expected->>'fromStatus') IS DISTINCT FROM from_status OR expected->>'remarks' IS DISTINCT FROM remarks THEN RAISE EXCEPTION USING ERRCODE='42501',CONSTRAINT='rev869b_exact_command_slot',MESSAGE='Exact command slot mismatch'; END IF;
          INSERT INTO nexa.rev869b_command_claims("ContextToken","ClaimKind","HistoryId","EntityType","EntityId","Operation","ParentVersion","FromStatus","ToStatus","Correlation","RemarksSha256") VALUES(token,claim_kind,history_id,entity_type,entity_id,operation,parent_version,from_status,to_status,correlation,digest(remarks,'sha256'));
        END $f$;
        CREATE FUNCTION nexa.rev869b_commit_command_attempt(attempt_id uuid,business_sha bytea,response_json jsonb,receipt_id uuid)
        RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,nexa AS $f$ DECLARE command_id uuid; expected integer; actual integer; exact_business_sha bytea; BEGIN
          IF session_user<>'nexa_rev869b_app_runtime' OR octet_length(business_sha)<>32 THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Exact runtime commit required'; END IF;
          SELECT a."CommandId",c."SlotCount",c."SlotSha256" INTO STRICT command_id,expected,exact_business_sha FROM nexa.rev869b_command_attempts a JOIN nexa.rev869b_command_contexts c ON c."AttemptId"=a."AttemptId" WHERE a."AttemptId"=attempt_id AND a."IsActive" AND c."BackendPid"=pg_backend_pid() AND c."TransactionId"=txid_current(); SELECT count(*) INTO actual FROM nexa.rev869b_command_claims q JOIN nexa.rev869b_command_contexts c ON c."ContextToken"=q."ContextToken" WHERE c."AttemptId"=attempt_id;
          IF business_sha<>exact_business_sha THEN RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='rev869b_command_business_fingerprint',MESSAGE='Committed business fingerprint mismatch'; END IF;
          IF actual<>expected THEN RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='rev869b_command_claim_coverage',MESSAGE='Claim coverage mismatch'; END IF;
          INSERT INTO nexa.rev869b_command_receipts VALUES(receipt_id,attempt_id,command_id,exact_business_sha,response_json,transaction_timestamp()); INSERT INTO nexa.rev869b_command_attempt_outcomes VALUES(gen_random_uuid(),attempt_id,'Committed',NULL,exact_business_sha,transaction_timestamp(),session_user); UPDATE nexa.rev869b_command_attempts SET "IsActive"=false WHERE "AttemptId"=attempt_id; RETURN receipt_id;
        END $f$;
        CREATE FUNCTION nexa.rev869b_record_noncommit_outcome(attempt_id uuid,execution_instance uuid,service_sha bytea,ownership_sha bytea,terminal_state text,category text,outcome_id uuid)
        RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,nexa AS $f$ DECLARE existing nexa.rev869b_command_attempt_outcomes%ROWTYPE; BEGIN
          IF session_user<>'nexa_rev869b_command_audit' OR terminal_state NOT IN ('Rejected','RolledBack','Abandoned') OR length(category) NOT BETWEEN 1 AND 100 OR octet_length(service_sha)<>32 OR octet_length(ownership_sha)<>32 THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Exact noncommit outcome required'; END IF;
          IF terminal_state IN ('RolledBack','Abandoned') AND (NOT pg_try_advisory_xact_lock(hashtextextended(attempt_id::text,86923)) OR NOT pg_try_advisory_xact_lock(hashtextextended(attempt_id::text,86924))) THEN RAISE EXCEPTION USING ERRCODE='42501',CONSTRAINT='rev869b_transaction_still_active',MESSAGE='The exact command transaction is still active'; END IF;

          SELECT * INTO existing FROM nexa.rev869b_command_attempt_outcomes WHERE "AttemptId"=attempt_id;
          IF FOUND THEN IF existing."OutcomeId"<>outcome_id OR existing."TerminalState"<>terminal_state OR existing."Category"<>category OR existing."RecordedBy"<>session_user OR NOT EXISTS(SELECT 1 FROM nexa.rev869b_command_attempts a WHERE a."AttemptId"=attempt_id AND a."ExecutionInstanceId"=execution_instance AND a."ServiceInstanceSha256"=service_sha AND a."OwnershipLeaseSha256"=ownership_sha) THEN RAISE EXCEPTION USING ERRCODE='23505',CONSTRAINT='rev869b_noncommit_replay_mismatch',MESSAGE='Noncommit outcome replay mismatch'; END IF; RETURN existing."OutcomeId"; END IF;
          IF NOT EXISTS(
            SELECT 1 FROM nexa.rev869b_command_attempts a
            WHERE a."AttemptId"=attempt_id AND a."IsActive" AND a."ExecutionInstanceId"=execution_instance
              AND a."ServiceInstanceSha256"=service_sha AND a."OwnershipLeaseSha256"=ownership_sha
              AND (
                (terminal_state='Rejected' AND NOT EXISTS(SELECT 1 FROM nexa.rev869b_command_contexts c WHERE c."AttemptId"=a."AttemptId"))
                OR
                (terminal_state='RolledBack'
                  AND NOT EXISTS(SELECT 1 FROM nexa.rev869b_command_receipts r WHERE r."AttemptId"=a."AttemptId")
                  AND NOT EXISTS(SELECT 1 FROM nexa.rev869b_command_contexts c WHERE c."AttemptId"=a."AttemptId" AND (c."BackendPid"<>a."TargetBackendPid" OR c."TransactionId"<>a."TargetTransactionId")))
                OR
                (terminal_state='Abandoned' AND (
                  NOT EXISTS(SELECT 1 FROM nexa.rev869b_command_contexts c WHERE c."AttemptId"=a."AttemptId")
                  OR EXISTS(
                    SELECT 1 FROM nexa.rev869b_command_contexts c
                    WHERE c."AttemptId"=a."AttemptId" AND c."BackendPid"=a."TargetBackendPid" AND c."TransactionId"=a."TargetTransactionId"
                )))
              ))
            OR EXISTS(SELECT 1 FROM nexa.rev869b_command_receipts WHERE "AttemptId"=attempt_id)
          THEN RAISE EXCEPTION USING ERRCODE='42501',CONSTRAINT='rev869b_noncommit_terminalizer_binding',MESSAGE='Noncommit terminalizer binding or authoritative no-commit proof mismatch'; END IF;
          INSERT INTO nexa.rev869b_command_attempt_outcomes VALUES(outcome_id,attempt_id,terminal_state,category,NULL,clock_timestamp(),session_user); UPDATE nexa.rev869b_command_attempts SET "IsActive"=false WHERE "AttemptId"=attempt_id AND "IsActive" AND "ExecutionInstanceId"=execution_instance AND "ServiceInstanceSha256"=service_sha AND "OwnershipLeaseSha256"=ownership_sha; IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='Attempt terminalization conflict'; END IF; RETURN outcome_id;
        END $f$;
        CREATE FUNCTION nexa.rev869b_reconcile_command_attempt(attempt_id uuid) RETURNS jsonb LANGUAGE sql SECURITY DEFINER STABLE SET search_path=pg_catalog,nexa AS $f$ SELECT jsonb_build_object('attemptId',a."AttemptId",'ordinal',a."AttemptOrdinal",'active',a."IsActive",'terminal',o."TerminalState",'receiptId',r."ReceiptId",'response',r."ResponseJson") FROM nexa.rev869b_command_attempts a LEFT JOIN nexa.rev869b_command_attempt_outcomes o ON o."AttemptId"=a."AttemptId" LEFT JOIN nexa.rev869b_command_receipts r ON r."AttemptId"=a."AttemptId" WHERE a."AttemptId"=$1 AND session_user IN ('nexa_rev869b_command_audit','nexa_rev869b_target_verifier') $f$;
        CREATE FUNCTION nexa.rev869b_read_target_security_state() RETURNS TABLE(request_count bigint,context_count bigint,receipt_count bigint,outcome_count bigint,attempt_count bigint,attempt_sha256 text,target_instance_sha256 text) LANGUAGE sql SECURITY DEFINER STABLE SET search_path=pg_catalog,nexa AS $f$
          SELECT (SELECT count(*) FROM nexa.rev869b_command_requests),(SELECT count(*) FROM nexa.rev869b_command_contexts),(SELECT count(*) FROM nexa.rev869b_command_receipts),(SELECT count(*) FROM nexa.rev869b_command_attempt_outcomes),(SELECT count(*) FROM nexa.rev869b_command_attempts),(SELECT encode(digest(coalesce(string_agg("AttemptId"::text,',' ORDER BY "AttemptId"),''),'sha256'),'hex') FROM nexa.rev869b_command_attempts),(SELECT encode("InstanceSha256",'hex') FROM nexa.rev869b_target_instance_identity WHERE "IdentityId") WHERE session_user='nexa_rev869b_target_verifier' $f$;
        CREATE FUNCTION nexa.rev869b_read_command_evidence(command_id uuid,attempt_id uuid) RETURNS jsonb LANGUAGE sql SECURITY DEFINER STABLE SET search_path=pg_catalog,nexa AS $f$
          SELECT jsonb_build_object(
            'targetIdentity',(SELECT jsonb_build_object('instanceId',i."InstanceId",'databaseName',i."DatabaseName",'instanceSha256',encode(i."InstanceSha256",'hex')) FROM nexa.rev869b_target_instance_identity i WHERE i."IdentityId"),
            'request',(SELECT jsonb_build_object('commandId',r."CommandId",'organizationId',r."OrganizationId",'operation',r."Operation",'idempotencyKeySha256',encode(r."IdempotencyKeySha256",'hex'),'requestSha256',encode(r."RequestSha256",'hex'),'actorEmployeeId',r."ActorEmployeeId",'identityIssuer',r."IdentityIssuer",'identitySubject',r."IdentitySubject",'actorRole',r."ActorRole") FROM nexa.rev869b_command_requests r WHERE r."CommandId"=$1),
            'requestCount',(SELECT count(*) FROM nexa.rev869b_command_requests r WHERE r."CommandId"=$1),
            'attempt',(SELECT to_jsonb(a) FROM nexa.rev869b_command_attempts a WHERE a."CommandId"=$1 AND a."AttemptId"=$2),
            'attemptCount',(SELECT count(*) FROM nexa.rev869b_command_attempts a WHERE a."CommandId"=$1 AND a."AttemptId"=$2),
            'activeAttemptCount',(SELECT count(*) FROM nexa.rev869b_command_attempts a WHERE a."CommandId"=$1 AND a."IsActive"),
            'context',(SELECT to_jsonb(x) FROM nexa.rev869b_command_contexts x WHERE x."AttemptId"=$2),
            'contextCount',(SELECT count(*) FROM nexa.rev869b_command_contexts x WHERE x."AttemptId"=$2),
            'claims',coalesce((SELECT jsonb_agg(to_jsonb(q) ORDER BY q."ClaimId") FROM nexa.rev869b_command_claims q JOIN nexa.rev869b_command_contexts x ON x."ContextToken"=q."ContextToken" WHERE x."AttemptId"=$2),'[]'::jsonb),
            'businessRows',coalesce((SELECT jsonb_agg(jsonb_build_object('claimId',q."ClaimId",'entityType',q."EntityType",'entityId',q."EntityId",'operation',q."Operation",'parentVersion',q."ParentVersion",'toStatus',q."ToStatus",'correlation',q."Correlation") ORDER BY q."ClaimId") FROM nexa.rev869b_command_claims q JOIN nexa.rev869b_command_contexts x ON x."ContextToken"=q."ContextToken" WHERE x."AttemptId"=$2 AND q."ClaimKind"='Business'),'[]'::jsonb),
            'historyRows',coalesce((SELECT jsonb_agg(jsonb_build_object('claimId',q."ClaimId",'historyId',q."HistoryId",'entityType',q."EntityType",'entityId',q."EntityId",'fromStatus',q."FromStatus",'toStatus',q."ToStatus",'correlation',q."Correlation",'remarksSha256',encode(q."RemarksSha256",'hex')) ORDER BY q."ClaimId") FROM nexa.rev869b_command_claims q JOIN nexa.rev869b_command_contexts x ON x."ContextToken"=q."ContextToken" WHERE x."AttemptId"=$2 AND q."ClaimKind"<>'Business'),'[]'::jsonb),
            'businessRowCount',(SELECT count(*) FROM nexa.rev869b_command_claims q JOIN nexa.rev869b_command_contexts x ON x."ContextToken"=q."ContextToken" WHERE x."AttemptId"=$2 AND q."ClaimKind"='Business'),
            'historyRowCount',(SELECT count(*) FROM nexa.rev869b_command_claims q JOIN nexa.rev869b_command_contexts x ON x."ContextToken"=q."ContextToken" WHERE x."AttemptId"=$2 AND q."ClaimKind"<>'Business'),
            'claimSha256',(SELECT encode(digest(coalesce(string_agg(q."ClaimKind"||':'||q."HistoryId"::text||':'||q."EntityType"||':'||q."EntityId"::text||':'||q."Operation"||':'||q."ParentVersion"::text||':'||coalesce(q."FromStatus",'')||':'||q."ToStatus"||':'||q."Correlation"||':'||encode(q."RemarksSha256",'hex'),',' ORDER BY q."ClaimId"),''),'sha256'),'hex') FROM nexa.rev869b_command_claims q JOIN nexa.rev869b_command_contexts x ON x."ContextToken"=q."ContextToken" WHERE x."AttemptId"=$2),
            'outcome',(SELECT to_jsonb(o) FROM nexa.rev869b_command_attempt_outcomes o WHERE o."AttemptId"=$2),
            'receipt',(SELECT jsonb_build_object('receiptId',x."ReceiptId",'commandId',x."CommandId",'businessSha256',encode(x."BusinessSha256",'hex'),'responseSha256',encode(digest(x."ResponseJson"::text,'sha256'),'hex')) FROM nexa.rev869b_command_receipts x WHERE x."AttemptId"=$2),
            'receiptCount',(SELECT count(*) FROM nexa.rev869b_command_receipts x WHERE x."AttemptId"=$2),
            'outcomeCount',(SELECT count(*) FROM nexa.rev869b_command_attempt_outcomes o WHERE o."AttemptId"=$2),
            'allAttemptIds',coalesce((SELECT jsonb_agg(a."AttemptId" ORDER BY a."AttemptOrdinal") FROM nexa.rev869b_command_attempts a WHERE a."CommandId"=$1),'[]'::jsonb))
          WHERE $1<>'00000000-0000-0000-0000-000000000000'::uuid AND $2<>'00000000-0000-0000-0000-000000000000'::uuid AND session_user='nexa_rev869b_target_verifier' $f$;

        CREATE FUNCTION nexa.rev869b_read_purge_evidence(authorization_id uuid,purge_attempt_id uuid) RETURNS jsonb LANGUAGE sql SECURITY DEFINER STABLE SET search_path=pg_catalog,nexa AS $f$
          SELECT jsonb_build_object(
            'targetIdentity',(SELECT jsonb_build_object('instanceId',i."InstanceId",'databaseName',i."DatabaseName",'instanceSha256',encode(i."InstanceSha256",'hex')) FROM nexa.rev869b_target_instance_identity i WHERE i."IdentityId"),
            'authorization',(SELECT to_jsonb(a)-'NonceSha256' FROM nexa.rev869b_purge_authorizations a WHERE a."AuthorizationId"=$1),
            'authorizationCount',(SELECT count(*) FROM nexa.rev869b_purge_authorizations a WHERE a."AuthorizationId"=$1),
            'attempt',(SELECT to_jsonb(p) FROM nexa.rev869b_purge_attempts p WHERE p."AuthorizationId"=$1 AND p."PurgeAttemptId"=$2),
            'attemptCount',(SELECT count(*) FROM nexa.rev869b_purge_attempts p WHERE p."AuthorizationId"=$1 AND p."PurgeAttemptId"=$2),
            'rootAuthorization',(SELECT to_jsonb(root)-'NonceSha256' FROM nexa.rev869b_purge_authorizations a JOIN nexa.rev869b_purge_authorizations root ON root."AuthorizationId"=a."RootAuthorizationId" WHERE a."AuthorizationId"=$1),
            'priorAttempt',(SELECT to_jsonb(prior) FROM nexa.rev869b_purge_authorizations a JOIN nexa.rev869b_purge_attempts prior ON prior."PurgeAttemptId"=a."PriorAttemptId" WHERE a."AuthorizationId"=$1),
            'eligibleRows',coalesce((SELECT jsonb_agg(jsonb_build_object('ledgerName','command_contexts','rowId',x."ContextToken") ORDER BY x."ContextToken") FROM (SELECT c."ContextToken" FROM nexa.rev869b_command_contexts c JOIN nexa.rev869b_command_attempts ca ON ca."AttemptId"=c."AttemptId" JOIN nexa.rev869b_command_requests cr ON cr."CommandId"=ca."CommandId" JOIN nexa.rev869b_purge_authorizations a ON a."AuthorizationId"=$1 WHERE cr."OrganizationId"=substring(a."Scope" from 14) AND c."OpenedAt"<a."Cutoff" ORDER BY c."ContextToken" LIMIT a."MaximumRows") x),'[]'::jsonb),
            'candidates',coalesce((SELECT jsonb_agg(jsonb_build_object('ledgerName',c."LedgerName",'rowId',c."RowId") ORDER BY c."LedgerName",c."RowId") FROM nexa.rev869b_purge_candidates c WHERE c."PurgeAttemptId"=$2),'[]'::jsonb),
            'candidateCount',(SELECT count(*) FROM nexa.rev869b_purge_candidates c WHERE c."PurgeAttemptId"=$2),
            'candidateSha256',(SELECT encode(digest(coalesce(string_agg(c."LedgerName"||':'||c."RowId"::text,',' ORDER BY c."LedgerName",c."RowId"),''),'sha256'),'hex') FROM nexa.rev869b_purge_candidates c WHERE c."PurgeAttemptId"=$2),
            'currentCandidateRows',coalesce((SELECT jsonb_agg(jsonb_build_object('ledgerName',p."LedgerName",'rowId',p."RowId",'active',a."IsActive") ORDER BY p."LedgerName",p."RowId") FROM nexa.rev869b_purge_candidates p LEFT JOIN nexa.rev869b_command_contexts c ON c."ContextToken"=p."RowId" LEFT JOIN nexa.rev869b_command_attempts a ON a."AttemptId"=c."AttemptId" WHERE p."PurgeAttemptId"=$2),'[]'::jsonb),
            'contextRows',coalesce((SELECT jsonb_agg(jsonb_build_object('contextToken',c."ContextToken",'attemptId',c."AttemptId",'openedAt',c."OpenedAt") ORDER BY c."ContextToken") FROM nexa.rev869b_command_contexts c),'[]'::jsonb),
            'contextSha256',(SELECT encode(digest(coalesce(string_agg(c."ContextToken"::text||':'||c."AttemptId"::text,',' ORDER BY c."ContextToken"),''),'sha256'),'hex') FROM nexa.rev869b_command_contexts c),
            'events',coalesce((SELECT jsonb_agg(jsonb_build_object('eventId',e."EventId",'state',e."State",'evidenceSha256',encode(e."EvidenceSha256",'hex'),'principal',e."Principal") ORDER BY e."EventId") FROM nexa.rev869b_purge_events e WHERE e."PurgeAttemptId"=$2),'[]'::jsonb),
            'eventCount',(SELECT count(*) FROM nexa.rev869b_purge_events e WHERE e."PurgeAttemptId"=$2),
            'activeChildCount',(SELECT count(*) FROM nexa.rev869b_purge_authorizations child WHERE child."PriorAttemptId"=$2 AND child."State"<>'Expired'))
          WHERE $1<>'00000000-0000-0000-0000-000000000000'::uuid AND $2<>'00000000-0000-0000-0000-000000000000'::uuid AND session_user='nexa_rev869b_target_verifier' $f$;

        CREATE FUNCTION nexa.rev869b_read_export_evidence(authorization_id uuid,batch_id uuid,release_id uuid) RETURNS jsonb LANGUAGE sql SECURITY DEFINER STABLE SET search_path=pg_catalog,nexa AS $f$
          SELECT jsonb_build_object(
            'targetIdentity',(SELECT jsonb_build_object('instanceId',i."InstanceId",'databaseName',i."DatabaseName",'instanceSha256',encode(i."InstanceSha256",'hex')) FROM nexa.rev869b_target_instance_identity i WHERE i."IdentityId"),
            'authorization',(SELECT to_jsonb(a) FROM nexa.rev869b_export_authorizations a WHERE a."AuthorizationId"=$1),
            'authorizationCount',(SELECT count(*) FROM nexa.rev869b_export_authorizations a WHERE a."AuthorizationId"=$1),
            'batch',(SELECT to_jsonb(b) FROM nexa.rev869b_export_batches b WHERE b."AuthorizationId"=$1 AND b."BatchId"=$2),
            'batchCount',(SELECT count(*) FROM nexa.rev869b_export_batches b WHERE b."AuthorizationId"=$1 AND b."BatchId"=$2),
            'release',(SELECT to_jsonb(x) FROM nexa.rev869b_export_releases x WHERE x."BatchId"=$2 AND x."ReleaseId"=$3),
            'releases',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x."StartedAt",x."ReleaseId") FROM nexa.rev869b_export_releases x WHERE x."BatchId"=$2),'[]'::jsonb),
            'activeReleaseCount',(SELECT count(*) FROM nexa.rev869b_export_releases x WHERE x."BatchId"=$2 AND x."State"='ReleaseStarted'),
            'deliveredReleaseCount',(SELECT count(*) FROM nexa.rev869b_export_releases x WHERE x."BatchId"=$2 AND x."State"='Delivered'),
            'rows',coalesce((SELECT jsonb_agg(jsonb_build_object('ordinal',r."Ordinal",'fieldKeys',(SELECT jsonb_agg(k ORDER BY k) FROM jsonb_object_keys(r."Payload") k),'storedSha256',encode(r."RowSha256",'hex'),'recomputedSha256',encode(digest(r."Payload"::text,'sha256'),'hex')) ORDER BY r."Ordinal") FROM nexa.rev869b_export_batch_rows r WHERE r."BatchId"=$2),'[]'::jsonb),
            'rowCount',(SELECT count(*) FROM nexa.rev869b_export_batch_rows r WHERE r."BatchId"=$2),
            'recomputedBatchSha256',(SELECT encode(digest(coalesce(string_agg(encode(digest(r."Payload"::text,'sha256'),'hex'),',' ORDER BY r."Ordinal"),''),'sha256'),'hex') FROM nexa.rev869b_export_batch_rows r WHERE r."BatchId"=$2))
          WHERE $1<>'00000000-0000-0000-0000-000000000000'::uuid AND $2<>'00000000-0000-0000-0000-000000000000'::uuid AND ($3 IS NULL OR $3<>'00000000-0000-0000-0000-000000000000'::uuid) AND session_user='nexa_rev869b_target_verifier' $f$;

        CREATE FUNCTION nexa.rev869b_read_target_acl_evidence() RETURNS jsonb LANGUAGE sql SECURITY DEFINER STABLE SET search_path=pg_catalog,nexa AS $f$
          WITH facts(fact) AS (
            SELECT 'database|'||current_database()||'|'||pg_get_userbyid(d.datdba)||'|'||coalesce(d.datacl::text,'') FROM pg_database d WHERE d.datname=current_database()
            UNION ALL SELECT 'schema|'||n.nspname||'|'||pg_get_userbyid(n.nspowner)||'|'||coalesce(n.nspacl::text,'') FROM pg_namespace n WHERE n.nspname='nexa'
            UNION ALL SELECT 'relation|'||c.oid::regclass::text||'|'||pg_get_userbyid(c.relowner)||'|'||coalesce(c.relacl::text,'') FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='nexa'
            UNION ALL SELECT 'function|'||p.oid::regprocedure::text||'|'||pg_get_userbyid(p.proowner)||'|'||coalesce(p.proacl::text,'') FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='nexa'
            UNION ALL SELECT 'defaultacl|'||pg_get_userbyid(d.defaclrole)||'|'||d.defaclobjtype||'|'||coalesce(d.defaclacl::text,'') FROM pg_default_acl d WHERE d.defaclnamespace='nexa'::regnamespace
            UNION ALL SELECT 'role|'||r.rolname||'|'||r.rolcanlogin||'|'||r.rolinherit||'|'||r.rolsuper||'|'||r.rolcreatedb||'|'||r.rolcreaterole||'|'||r.rolreplication||'|'||r.rolbypassrls FROM pg_roles r WHERE r.rolname LIKE 'nexa_rev869b_%')
          SELECT jsonb_build_object(
            'targetIdentity',(SELECT jsonb_build_object('instanceId',i."InstanceId",'databaseName',i."DatabaseName",'instanceSha256',encode(i."InstanceSha256",'hex')) FROM nexa.rev869b_target_instance_identity i WHERE i."IdentityId"),
            'facts',jsonb_agg(fact ORDER BY fact),'count',count(*),'sha256',encode(digest(string_agg(fact,E'\n' ORDER BY fact),'sha256'),'hex'),
            'ownerFacts',jsonb_agg(fact ORDER BY fact) FILTER(WHERE fact LIKE 'database|%' OR fact LIKE 'schema|%' OR fact LIKE 'relation|%' OR fact LIKE 'function|%'),
            'defaultPrivilegeFacts',jsonb_agg(fact ORDER BY fact) FILTER(WHERE fact LIKE 'defaultacl|%'),
            'roleFacts',jsonb_agg(fact ORDER BY fact) FILTER(WHERE fact LIKE 'role|%'),
            'protectedStateSha256',(SELECT encode(digest((SELECT count(*) FROM nexa.rev869b_command_requests)::text||':'||(SELECT count(*) FROM nexa.rev869b_command_attempts)::text||':'||(SELECT count(*) FROM nexa.rev869b_command_attempt_outcomes)::text||':'||(SELECT count(*) FROM nexa.rev869b_purge_authorizations)::text||':'||(SELECT count(*) FROM nexa.rev869b_export_batches)::text,'sha256'),'hex'))
          FROM facts WHERE session_user='nexa_rev869b_target_verifier' $f$;
        CREATE FUNCTION nexa.rev869b_canonical_json_v3(value jsonb) RETURNS text LANGUAGE sql IMMUTABLE STRICT SET search_path=pg_catalog AS $f$
          SELECT CASE jsonb_typeof($1)
            WHEN 'object' THEN coalesce((SELECT '{'||string_agg(to_jsonb(key)::text||':'||nexa.rev869b_canonical_json_v3(val),',' ORDER BY key COLLATE "C")||'}' FROM jsonb_each($1) e(key,val)),'{}')
            WHEN 'array' THEN coalesce((SELECT '['||string_agg(nexa.rev869b_canonical_json_v3(val),',' ORDER BY ordinal)||']' FROM jsonb_array_elements($1) WITH ORDINALITY e(val,ordinal)),'[]')
            ELSE $1::text END $f$;
        CREATE FUNCTION nexa.rev869b_build_raw_facts_v3(reader_id text,scope jsonb,observation_stage text,requested_facts text[],allowed jsonb,actual_values jsonb) RETURNS jsonb LANGUAGE sql VOLATILE SET search_path=pg_catalog,nexa AS $f$
          WITH requested AS (
            SELECT u.name,u.ordinality,a.value#>>'{type}' value_type,a.value#>>'{kind}' kind
            FROM unnest($4) WITH ORDINALITY u(name,ordinality) JOIN LATERAL (SELECT $5->u.name value) a ON a.value IS NOT NULL
          ), fact_rows AS (
            SELECT jsonb_build_object('kind',r.kind,'name',r.name,'valueType',r.value_type,'value',$6->r.name,'sourceRowCount',1,
              'sourceSha256',encode(digest($1||':'||r.name||':'||($6->r.name)::text||':'||$2::text,'sha256'),'hex')) fact,r.ordinality FROM requested r WHERE $6?r.name
          ), base AS (
            SELECT jsonb_build_object('readerSchemaVersion','REV869B-FACTS-v3','readerId',$1,'scope',$2,'observedAtUtc',to_char(statement_timestamp() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
              'transactionBoundary','tx:'||txid_current_snapshot()::text||':'||$3||':'||($2->>'scenarioExecutionId'),'facts',coalesce((SELECT jsonb_agg(fact ORDER BY ordinality) FROM fact_rows),'[]'::jsonb),'factCount',(SELECT count(*) FROM fact_rows)) payload)
          SELECT payload||jsonb_build_object('rawSha256',encode(digest(nexa.rev869b_canonical_json_v3(payload),'sha256'),'hex')) FROM base
          WHERE $1 IN ('TC3','TP3','TE3','TA3') AND $3 IN ('Before','After','Durable','Cleanup')
            AND coalesce(cardinality($4),0)=(SELECT count(*) FROM requested) AND coalesce(cardinality($4),0)=(SELECT count(DISTINCT name) FROM requested)
            AND coalesce(cardinality($4),0)=(SELECT count(*) FROM fact_rows) $f$;

        CREATE FUNCTION nexa.rev869b_read_command_facts_v3(organization_id text,instance_sha bytea,lease_id uuid,lease_version bigint,command_id uuid,attempt_id uuid,scenario_execution_id uuid,observation_stage text,requested_facts text[]) RETURNS jsonb LANGUAGE sql SECURITY DEFINER VOLATILE SET search_path=pg_catalog,nexa AS $f$
          WITH identity AS (SELECT i.* FROM nexa.rev869b_target_instance_identity i WHERE i."IdentityId" AND i."InstanceSha256"=$2 AND i."LeaseId"=$3),
          request AS (SELECT r.* FROM nexa.rev869b_command_requests r WHERE r."OrganizationId"=$1 AND r."CommandId"=$5),
          attempt AS (SELECT a.* FROM nexa.rev869b_command_attempts a JOIN request r ON r."CommandId"=a."CommandId" WHERE a."AttemptId"=$6),
          contexts AS (SELECT c.* FROM nexa.rev869b_command_contexts c JOIN attempt a ON a."AttemptId"=c."AttemptId"),
          claims AS (SELECT q.* FROM nexa.rev869b_command_claims q JOIN contexts c ON c."ContextToken"=q."ContextToken"),
          outcomes AS (SELECT o.* FROM nexa.rev869b_command_attempt_outcomes o JOIN attempt a ON a."AttemptId"=o."AttemptId"),
          receipts AS (SELECT r.* FROM nexa.rev869b_command_receipts r JOIN attempt a ON a."AttemptId"=r."AttemptId"),
          snap AS (SELECT
            (SELECT count(*) FROM claims WHERE "ClaimKind"='Business') business_count,(SELECT count(*) FROM claims WHERE "ClaimKind"<>'Business') history_count,
            (SELECT count(*) FROM receipts) receipt_count,(SELECT count(*) FROM outcomes WHERE "TerminalState"='Committed') committed_count,
            (SELECT count(*) FROM outcomes WHERE "TerminalState"='RolledBack') rollback_count,(SELECT count(*) FROM attempt WHERE "IsActive") active_count,
            (SELECT count(*) FROM request) request_count,(SELECT count(*) FROM attempt) attempt_count,
            encode(digest(coalesce((SELECT string_agg("ClaimId"::text||':'||"ClaimKind"||':'||"HistoryId"::text||':'||"EntityId"::text,',' ORDER BY "ClaimId") FROM claims),''),'sha256'),'hex') claim_sha,
            coalesce((SELECT "ReceiptId" FROM receipts LIMIT 1),$6) receipt_id,
            coalesce((SELECT encode(digest("ResponseJson"::text,'sha256'),'hex') FROM receipts LIMIT 1),encode(digest('','sha256'),'hex')) response_sha,
            coalesce((SELECT encode("RequestSha256",'hex') FROM request LIMIT 1),encode(digest('','sha256'),'hex')) request_sha),
          allowed AS (SELECT jsonb_object_agg(name,jsonb_build_object('type',typ,'kind',kind)) value FROM (VALUES
