            encode(digest(coalesce((SELECT string_agg("LedgerName"||':'||"RowId"::text,',' ORDER BY "LedgerName","RowId") FROM candidates),''),'sha256'),'hex') candidate_sha,
            encode(digest(coalesce((SELECT string_agg("ContextToken"::text||':'||"AttemptId"::text,',' ORDER BY "ContextToken") FROM eligible),''),'sha256'),'hex') context_sha),
          allowed AS (SELECT jsonb_object_agg(name,jsonb_build_object('type',typ,'kind',kind)) value FROM (VALUES
            ('startedAttemptCount','int64','selector'),('candidateCount','int64','selector'),('purgeEventCount','int64','selector'),('eligibleBeforeCount','int64','selector'),('frozenCandidateCount','int64','selector'),('deletedRowCount','int64','selector'),('zeroRowsEventCount','int64','selector'),('remainingEligibleCount','int64','selector'),('succeededEventCount','int64','selector'),('currentCandidateSha256','sha256','selector'),('contextAfterSha256','sha256','selector'),('failedEventCount','int64','selector'),('concurrentStartCount','int64','selector'),('consumedAuthorizationCount','int64','selector'),('executionCount','int64','selector'),('activeChildCount','int64','selector'),('substitutedChildCount','int64','selector'),
            ('frozenCandidateSha256','sha256','reference'),('contextBeforeSha256','sha256','reference')) x(name,typ,kind)),
          vals AS (SELECT jsonb_build_object('startedAttemptCount',attempt_count,'candidateCount',candidate_count,'purgeEventCount',event_count,'eligibleBeforeCount',eligible_count,'frozenCandidateCount',candidate_count,'deletedRowCount',CASE WHEN success_count=1 THEN candidate_count ELSE 0 END,'zeroRowsEventCount',zero_count,'remainingEligibleCount',CASE WHEN success_count=1 THEN 0 ELSE eligible_count END,'succeededEventCount',success_count,'currentCandidateSha256',candidate_sha,'contextAfterSha256',context_sha,'failedEventCount',failure_count,'concurrentStartCount',attempt_count,'consumedAuthorizationCount',consumed_count,'executionCount',attempt_count,'activeChildCount',child_count,'substitutedChildCount',0,'frozenCandidateSha256',candidate_sha,'contextBeforeSha256',context_sha) value FROM snap)
          SELECT nexa.rev869b_build_raw_facts_v3('TP3',jsonb_build_object('companyId',$1,'targetInstanceSha256',encode($2,'hex'),'leaseId',$3,'leaseVersion',$4,'operationId',$9,'scenarioExecutionId',$10,'stage',$11),$11,$12,allowed.value,vals.value)
          FROM allowed,vals WHERE session_user='nexa_rev869b_target_verifier' AND length($1)>0 AND EXISTS(SELECT 1 FROM identity) AND EXISTS(SELECT 1 FROM authorization) AND EXISTS(SELECT 1 FROM root_auth) AND EXISTS(SELECT 1 FROM attempt) AND $3<>'00000000-0000-0000-0000-000000000000'::uuid AND $4>0 AND $5<>'00000000-0000-0000-0000-000000000000'::uuid AND $6=$9 AND $7<>'00000000-0000-0000-0000-000000000000'::uuid AND $8<>'00000000-0000-0000-0000-000000000000'::uuid AND $10<>'00000000-0000-0000-0000-000000000000'::uuid $f$;
        CREATE FUNCTION nexa.rev869b_read_purge_evidence_v2(instance_sha bytea,lease_id uuid,scenario_id text,subcase_id text,authorization_id uuid,root_authorization_id uuid,batch_id uuid,purge_attempt_id uuid) RETURNS jsonb LANGUAGE sql SECURITY DEFINER STABLE SET search_path=pg_catalog,nexa AS $f$
          WITH identity AS (
