        CREATE FUNCTION nexa.rev869b_read_export_facts_v3(organization_id text,instance_sha bytea,lease_id uuid,lease_version bigint,authorization_id uuid,batch_id uuid,release_id uuid,as_of timestamptz,scenario_execution_id uuid,observation_stage text,operation_id uuid,requested_facts text[]) RETURNS jsonb LANGUAGE sql SECURITY DEFINER VOLATILE SET search_path=pg_catalog,nexa AS $f$
