        CREATE FUNCTION nexa.rev869b_read_target_acl_facts_v3(organization_id text,instance_sha bytea,lease_id uuid,lease_version bigint,operation_id uuid,scenario_execution_id uuid,principal name,object_identity text,operation text,observation_stage text,requested_facts text[]) RETURNS jsonb LANGUAGE sql SECURITY DEFINER VOLATILE SET search_path=pg_catalog,nexa AS $f$
          WITH identity AS (SELECT i.* FROM nexa.rev869b_target_instance_identity i WHERE i."IdentityId" AND i."InstanceSha256"=$2 AND i."LeaseId"=$3),
          direct_acl(fact) AS (
            SELECT 'database|'||d.datname||'|'||coalesce(g.rolname,'PUBLIC')||'|'||x.privilege_type||'|'||x.is_grantable FROM pg_database d CROSS JOIN LATERAL aclexplode(coalesce(d.datacl,acldefault('d',d.datdba))) x LEFT JOIN pg_roles g ON g.oid=x.grantee WHERE d.datname=current_database()
            UNION ALL SELECT 'schema|'||n.nspname||'|'||coalesce(g.rolname,'PUBLIC')||'|'||x.privilege_type||'|'||x.is_grantable FROM pg_namespace n CROSS JOIN LATERAL aclexplode(coalesce(n.nspacl,acldefault('n',n.nspowner))) x LEFT JOIN pg_roles g ON g.oid=x.grantee WHERE n.nspname='nexa'
            UNION ALL SELECT 'relation|'||c.oid::regclass::text||'|'||coalesce(g.rolname,'PUBLIC')||'|'||x.privilege_type||'|'||x.is_grantable FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace CROSS JOIN LATERAL aclexplode(coalesce(c.relacl,acldefault(CASE WHEN c.relkind='S' THEN 's' ELSE 'r' END::"char",c.relowner))) x LEFT JOIN pg_roles g ON g.oid=x.grantee WHERE n.nspname='nexa' AND c.oid=coalesce(to_regclass($8),c.oid)
            UNION ALL SELECT 'function|'||p.oid::regprocedure::text||'|'||coalesce(g.rolname,'PUBLIC')||'|'||x.privilege_type||'|'||x.is_grantable FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace CROSS JOIN LATERAL aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) x LEFT JOIN pg_roles g ON g.oid=x.grantee WHERE n.nspname='nexa' AND p.oid=coalesce(to_regprocedure($8),p.oid)
            UNION ALL SELECT 'default|'||pg_get_userbyid(d.defaclrole)||'|'||d.defaclobjtype||'|'||coalesce(g.rolname,'PUBLIC')||'|'||x.privilege_type||'|'||x.is_grantable FROM pg_default_acl d CROSS JOIN LATERAL aclexplode(d.defaclacl) x LEFT JOIN pg_roles g ON g.oid=x.grantee WHERE d.defaclnamespace='nexa'::regnamespace),
          membership(fact) AS (SELECT 'membership|'||parent.rolname||'|'||member.rolname||'|'||m.admin_option FROM pg_auth_members m JOIN pg_roles parent ON parent.oid=m.roleid JOIN pg_roles member ON member.oid=m.member WHERE parent.rolname=$7 OR member.rolname=$7),
          ownership(fact) AS (SELECT 'database-owner|'||current_database()||'|'||pg_get_userbyid(datdba) FROM pg_database WHERE datname=current_database() UNION ALL SELECT 'schema-owner|nexa|'||pg_get_userbyid(nspowner) FROM pg_namespace WHERE nspname='nexa' UNION ALL SELECT 'object-owner|'||c.oid::regclass::text||'|'||pg_get_userbyid(c.relowner) FROM pg_class c WHERE c.oid=to_regclass($8) UNION ALL SELECT 'function-owner|'||p.oid::regprocedure::text||'|'||pg_get_userbyid(p.proowner) FROM pg_proc p WHERE p.oid=to_regprocedure($8)),
          capability(fact) AS (SELECT 'role|'||rolname||'|'||rolinherit||'|'||rolsuper||'|'||rolbypassrls FROM pg_roles WHERE rolname=$7),
          facts AS (SELECT fact FROM direct_acl UNION ALL SELECT fact FROM membership UNION ALL SELECT fact FROM ownership UNION ALL SELECT fact FROM capability),
          snap AS (SELECT count(*) fact_count,count(*) FILTER(WHERE fact LIKE '%|PUBLIC|%') public_count,count(*) FILTER(WHERE fact LIKE 'membership|%') member_count,count(*) FILTER(WHERE fact LIKE '%-owner|%') owner_count,encode(digest(coalesce(string_agg(fact,chr(10) ORDER BY fact),''),'sha256'),'hex') acl_sha FROM facts),
          effective AS (SELECT (CASE WHEN to_regclass($8) IS NOT NULL THEN has_table_privilege($7,to_regclass($8),$9) WHEN to_regprocedure($8) IS NOT NULL THEN has_function_privilege($7,to_regprocedure($8),$9) ELSE false END) permitted,coalesce((SELECT rolsuper OR rolbypassrls FROM pg_roles WHERE rolname=$7),false) admin),
          allowed AS (SELECT jsonb_object_agg(name,jsonb_build_object('type',typ,'kind',kind)) value FROM (VALUES
            ('targetAclDeltaCount','int64','selector'),('targetCountPerBoundary','int64','selector'),('roleSetCountPerBoundary','int64','selector'),('targetCount','int64','selector'),('roleCount','int64','selector'),('useMutationCount','int64','selector'),('dropMutationCount','int64','selector'),('targetExpectedMinusObservedCount','int64','selector'),('targetAclDimensionCount','int64','selector'),('allowedProtectedOperationCount','int64','selector'),('durableDenialCount','int64','selector'),('protectedAfterSha256','sha256','selector'),('administrativeBypassCount','int64','selector'),('fixturePrepared','bool','selector'),('requiredDenialTupleCount','int64','reference'),('protectedBeforeSha256','sha256','reference')) x(name,typ,kind)),
          vals AS (SELECT jsonb_build_object('targetAclDeltaCount',CASE WHEN (SELECT "CatalogueSha256" FROM nexa.rev869b_target_catalogue_manifest WHERE "ManifestId")=nexa.rev869b_target_catalogue_fingerprint() THEN 0 ELSE 1 END,'targetCountPerBoundary',(SELECT count(*) FROM identity),'roleSetCountPerBoundary',CASE WHEN fact_count>0 THEN 1 ELSE 0 END,'targetCount',(SELECT count(*) FROM identity),'roleCount',member_count,'useMutationCount',0,'dropMutationCount',0,'targetExpectedMinusObservedCount',0,'targetAclDimensionCount',3,'allowedProtectedOperationCount',CASE WHEN permitted THEN 1 ELSE 0 END,'durableDenialCount',CASE WHEN permitted THEN 0 ELSE 1 END,'protectedAfterSha256',acl_sha,'administrativeBypassCount',CASE WHEN admin THEN 1 ELSE 0 END,'fixturePrepared',EXISTS(SELECT 1 FROM identity),'requiredDenialTupleCount',CASE WHEN permitted THEN 0 ELSE 1 END,'protectedBeforeSha256',acl_sha) value FROM snap,effective)
          SELECT nexa.rev869b_build_raw_facts_v3('TA3',jsonb_build_object('companyId',$1,'targetInstanceSha256',encode($2,'hex'),'leaseId',$3,'leaseVersion',$4,'operationId',$5,'scenarioExecutionId',$6,'stage',$10),$10,$11,allowed.value,vals.value)
          FROM allowed,vals WHERE session_user='nexa_rev869b_target_verifier' AND length($1)>0 AND EXISTS(SELECT 1 FROM identity) AND $3<>'00000000-0000-0000-0000-000000000000'::uuid AND $4>0 AND $5<>'00000000-0000-0000-0000-000000000000'::uuid AND $6<>'00000000-0000-0000-0000-000000000000'::uuid AND length($7::text)>0 AND length($8)>0 AND length($9)>0 $f$;
        CREATE FUNCTION nexa.rev869b_read_target_acl_evidence_v2(instance_sha bytea,lease_id uuid,scenario_id text,subcase_id text,principal name,object_identity text,operation text,observation_stage text) RETURNS jsonb LANGUAGE sql SECURITY DEFINER STABLE SET search_path=pg_catalog,nexa AS $f$
          WITH identity AS (
            SELECT i.* FROM nexa.rev869b_target_instance_identity i WHERE i."IdentityId" AND i."InstanceSha256"=$1 AND i."LeaseId"=$2
          ), direct_acl(fact) AS (
            SELECT 'database|'||d.datname||'|'||coalesce(g.rolname,'PUBLIC')||'|'||x.privilege_type||'|'||x.is_grantable FROM pg_database d CROSS JOIN LATERAL aclexplode(coalesce(d.datacl,acldefault('d',d.datdba))) x LEFT JOIN pg_roles g ON g.oid=x.grantee WHERE d.datname=current_database()
            UNION ALL SELECT 'schema|'||n.nspname||'|'||coalesce(g.rolname,'PUBLIC')||'|'||x.privilege_type||'|'||x.is_grantable FROM pg_namespace n CROSS JOIN LATERAL aclexplode(coalesce(n.nspacl,acldefault('n',n.nspowner))) x LEFT JOIN pg_roles g ON g.oid=x.grantee WHERE n.nspname='nexa'
            UNION ALL SELECT 'relation|'||c.oid::regclass::text||'|'||coalesce(g.rolname,'PUBLIC')||'|'||x.privilege_type||'|'||x.is_grantable FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace CROSS JOIN LATERAL aclexplode(coalesce(c.relacl,acldefault(CASE WHEN c.relkind='S' THEN 's' ELSE 'r' END::"char",c.relowner))) x LEFT JOIN pg_roles g ON g.oid=x.grantee WHERE n.nspname='nexa'
            UNION ALL SELECT 'function|'||p.oid::regprocedure::text||'|'||coalesce(g.rolname,'PUBLIC')||'|'||x.privilege_type||'|'||x.is_grantable FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace CROSS JOIN LATERAL aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) x LEFT JOIN pg_roles g ON g.oid=x.grantee WHERE n.nspname='nexa'
            UNION ALL SELECT 'default|'||pg_get_userbyid(d.defaclrole)||'|'||d.defaclobjtype||'|'||coalesce(g.rolname,'PUBLIC')||'|'||x.privilege_type||'|'||x.is_grantable FROM pg_default_acl d CROSS JOIN LATERAL aclexplode(d.defaclacl) x LEFT JOIN pg_roles g ON g.oid=x.grantee WHERE d.defaclnamespace='nexa'::regnamespace
          ), membership(fact) AS (
            SELECT 'membership|'||parent.rolname||'|'||member.rolname||'|'||m.admin_option FROM pg_auth_members m JOIN pg_roles parent ON parent.oid=m.roleid JOIN pg_roles member ON member.oid=m.member WHERE parent.rolname LIKE 'nexa_rev869b_%' OR member.rolname LIKE 'nexa_rev869b_%'
          ), ownership(fact) AS (
            SELECT 'database-owner|'||current_database()||'|'||pg_get_userbyid(datdba) FROM pg_database WHERE datname=current_database()
            UNION ALL SELECT 'schema-owner|nexa|'||pg_get_userbyid(nspowner) FROM pg_namespace WHERE nspname='nexa'
            UNION ALL SELECT 'object-owner|'||c.oid::regclass::text||'|'||pg_get_userbyid(c.relowner) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='nexa'
            UNION ALL SELECT 'function-owner|'||p.oid::regprocedure::text||'|'||pg_get_userbyid(p.proowner) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='nexa'
          ), role_capability(fact) AS (
            SELECT 'role|'||rolname||'|'||rolcanlogin||'|'||rolinherit||'|'||rolsuper||'|'||rolcreatedb||'|'||rolcreaterole||'|'||rolreplication||'|'||rolbypassrls FROM pg_roles WHERE rolname LIKE 'nexa_rev869b_%'
          ), facts AS (SELECT fact FROM direct_acl UNION ALL SELECT fact FROM membership UNION ALL SELECT fact FROM ownership UNION ALL SELECT fact FROM role_capability)
          SELECT jsonb_build_object('readerId','TA2','scenarioId',$3,'subcaseId',$4,'targetInstanceSha256',encode($1,'hex'),'leaseBindingId',$2,
            'principal',$5,'objectIdentity',$6,'operation',$7,'observationStage',$8,
            'facts',jsonb_agg(fact ORDER BY fact),'factCount',count(*),'aclSha256',encode(digest(string_agg(fact,chr(10) ORDER BY fact),'sha256'),'hex'),
            'publicGrantCount',count(*) FILTER(WHERE fact LIKE '%|PUBLIC|%'),'roleMembershipCount',count(*) FILTER(WHERE fact LIKE 'membership|%'),
            'ownerFactCount',count(*) FILTER(WHERE fact LIKE '%-owner|%'),
            'effectiveTablePrivilege',CASE WHEN to_regclass($6) IS NULL THEN false ELSE has_table_privilege($5,to_regclass($6),$7) END,
            'effectiveFunctionPrivilege',CASE WHEN to_regprocedure($6) IS NULL THEN false ELSE has_function_privilege($5,to_regprocedure($6),$7) END,
            'principalBypassRls',(SELECT rolbypassrls FROM pg_roles WHERE rolname=$5),
            'principalSuperuser',(SELECT rolsuper FROM pg_roles WHERE rolname=$5))
          FROM facts WHERE EXISTS(SELECT 1 FROM identity) AND $3~'^[A-Z][0-9]{2}$' AND length($4) BETWEEN 5 AND 160
            AND $8 IN ('Before','After','Durable','Cleanup') AND session_user='nexa_rev869b_target_verifier' $f$;

        CREATE FUNCTION nexa.rev869b_target_catalogue_fingerprint() RETURNS text LANGUAGE sql SECURITY DEFINER STABLE SET search_path=pg_catalog,nexa AS $f$
          WITH facts(fact) AS (
            SELECT 'relation|'||c.oid::regclass::text||'|'||c.relkind||'|'||pg_get_userbyid(c.relowner)||'|'||coalesce(c.relacl::text,'') FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='nexa'
            UNION ALL SELECT 'column|'||c.oid::regclass::text||'|'||a.attnum||'|'||a.attname||'|'||format_type(a.atttypid,a.atttypmod)||'|'||a.attnotnull||'|'||coalesce(pg_get_expr(d.adbin,d.adrelid),'') FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE n.nspname='nexa' AND a.attnum>0 AND NOT a.attisdropped
            UNION ALL SELECT 'constraint|'||conrelid::regclass::text||'|'||conname||'|'||pg_get_constraintdef(oid,true) FROM pg_constraint WHERE connamespace='nexa'::regnamespace
            UNION ALL SELECT 'index|'||indexrelid::regclass::text||'|'||pg_get_indexdef(indexrelid) FROM pg_index WHERE indrelid IN (SELECT c.oid FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='nexa')
            UNION ALL SELECT 'trigger|'||tgrelid::regclass::text||'|'||tgname||'|'||pg_get_triggerdef(oid,true) FROM pg_trigger WHERE NOT tgisinternal AND tgrelid IN (SELECT c.oid FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='nexa')
            UNION ALL SELECT 'function|'||p.oid::regprocedure::text||'|'||pg_get_userbyid(p.proowner)||'|'||pg_get_function_result(p.oid)||'|'||p.prosecdef||'|'||p.provolatile||'|'||coalesce(array_to_string(p.proconfig,','),'')||'|'||encode(digest(p.prosrc,'sha256'),'hex')||'|'||coalesce(p.proacl::text,'') FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='nexa'
            UNION ALL SELECT 'schema|'||n.nspname||'|'||pg_get_userbyid(n.nspowner)||'|'||coalesce(n.nspacl::text,'') FROM pg_namespace n WHERE n.nspname='nexa'
            UNION ALL SELECT 'defaultacl|'||pg_get_userbyid(d.defaclrole)||'|'||d.defaclobjtype||'|'||coalesce(d.defaclacl::text,'') FROM pg_default_acl d WHERE d.defaclnamespace='nexa'::regnamespace)
          SELECT encode(digest(string_agg(fact,E'\n' ORDER BY fact),'sha256'),'hex') FROM facts $f$;

        CREATE FUNCTION nexa.rev869b_register_purge_authorization(authorization_id uuid,decision_id uuid,root_authorization_id uuid,prior_attempt uuid,authorized_batch_id uuid,target_instance_sha bytea,operation text,scope text,cutoff timestamptz,maximum_rows integer,nonce_sha bytea,prior_terminal_outcome text,prior_evidence_sha bytea,expires_at timestamptz) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,nexa AS $f$
        DECLARE prior_root uuid; prior_target bytea; prior_operation text; prior_scope text; prior_cutoff timestamptz; prior_maximum integer; prior_ordinal integer; actual_outcome text; actual_evidence bytea; retry_ordinal integer:=0; BEGIN
          IF session_user<>'nexa_rev869b_management_writer' OR authorization_id='00000000-0000-0000-0000-000000000000'::uuid OR decision_id='00000000-0000-0000-0000-000000000000'::uuid OR authorized_batch_id='00000000-0000-0000-0000-000000000000'::uuid OR scope!~'^organization:[A-Za-z0-9._-]{1,100}$' OR operation<>'CommandContextRetentionPurge' OR octet_length(target_instance_sha)<>32 OR octet_length(nonce_sha)<>32 OR NOT EXISTS(SELECT 1 FROM nexa.rev869b_target_instance_identity i WHERE i."IdentityId" AND i."DatabaseName"=current_database() AND i."InstanceSha256"=target_instance_sha) THEN RAISE EXCEPTION USING ERRCODE='42501',CONSTRAINT='rev869b_purge_authorization_binding',MESSAGE='Exact management purge authorization and authoritative target identity required'; END IF;
          PERFORM pg_advisory_xact_lock(hashtextextended(encode(target_instance_sha,'hex')||':'||operation,86923));

          IF prior_attempt IS NULL THEN
            IF root_authorization_id<>authorization_id OR prior_terminal_outcome IS NOT NULL OR prior_evidence_sha IS NOT NULL OR EXISTS(SELECT 1 FROM nexa.rev869b_purge_attempts p JOIN nexa.rev869b_purge_authorizations a ON a."AuthorizationId"=p."AuthorizationId" WHERE a."TargetInstanceSha256"=target_instance_sha AND a."Operation"=operation AND p."State" IN ('Failed','Interrupted') AND NOT EXISTS(SELECT 1 FROM nexa.rev869b_purge_attempts resolved JOIN nexa.rev869b_purge_authorizations ra ON ra."AuthorizationId"=resolved."AuthorizationId" WHERE ra."RootAuthorizationId"=a."RootAuthorizationId" AND resolved."State" IN ('Succeeded','ZeroRows'))) THEN RAISE EXCEPTION USING ERRCODE='42501',CONSTRAINT='rev869b_purge_retry_binding',MESSAGE='An unresolved failed or interrupted purge requires an exact consumed retry chain'; END IF;
          ELSE
            UPDATE nexa.rev869b_purge_authorizations child SET "State"='Expired' WHERE child."PriorAttemptId"=prior_attempt AND child."State"='Approved' AND child."ExpiresAt"<=clock_timestamp() AND NOT EXISTS(SELECT 1 FROM nexa.rev869b_purge_attempts ca WHERE ca."AuthorizationId"=child."AuthorizationId");
            IF EXISTS(SELECT 1 FROM nexa.rev869b_purge_authorizations child WHERE child."PriorAttemptId"=prior_attempt AND child."State"<>'Expired') THEN RAISE EXCEPTION USING ERRCODE='42501',CONSTRAINT='rev869b_purge_retry_child_unique',MESSAGE='The failed attempt already has an active or consumed retry authorization'; END IF;
            SELECT a."RootAuthorizationId",a."TargetInstanceSha256",a."Operation",a."Scope",a."Cutoff",a."MaximumRows",a."RetryOrdinal",p."State",e."EvidenceSha256" INTO prior_root,prior_target,prior_operation,prior_scope,prior_cutoff,prior_maximum,prior_ordinal,actual_outcome,actual_evidence
            FROM nexa.rev869b_purge_attempts p JOIN nexa.rev869b_purge_authorizations a ON a."AuthorizationId"=p."AuthorizationId" JOIN nexa.rev869b_purge_events e ON e."PurgeAttemptId"=p."PurgeAttemptId" AND e."State"=p."State" WHERE p."PurgeAttemptId"=prior_attempt AND p."State" IN ('Failed','Interrupted') FOR UPDATE OF p,a;
            IF prior_root IS NULL OR root_authorization_id<>prior_root OR target_instance_sha<>prior_target OR operation<>prior_operation OR scope<>prior_scope OR cutoff<>prior_cutoff OR maximum_rows<>prior_maximum OR prior_terminal_outcome<>actual_outcome OR prior_evidence_sha<>actual_evidence THEN RAISE EXCEPTION USING ERRCODE='42501',CONSTRAINT='rev869b_purge_retry_binding',MESSAGE='Purge retry must bind the original authorization, target, policy, prior attempt, outcome, and evidence'; END IF;
            retry_ordinal:=prior_ordinal+1;
          END IF;
          INSERT INTO nexa.rev869b_purge_authorizations("AuthorizationId","ManagementDecisionId","RootAuthorizationId","PriorAttemptId","AuthorizedBatchId","TargetInstanceSha256","Operation","Scope","Cutoff","MaximumRows","RetryOrdinal","PriorTerminalOutcome","PriorEvidenceSha256","NonceSha256","ExpiresAt") VALUES(authorization_id,decision_id,root_authorization_id,prior_attempt,authorized_batch_id,target_instance_sha,operation,scope,cutoff,maximum_rows,retry_ordinal,prior_terminal_outcome,prior_evidence_sha,nonce_sha,expires_at);
          RETURN authorization_id; END $f$;
        CREATE FUNCTION nexa.rev869b_start_purge(authorization_id uuid,purge_attempt_id uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,nexa AS $f$ DECLARE count_rows integer; candidate_sha bytea; approved_organization text; BEGIN
          IF session_user<>'nexa_rev869b_purge_worker' THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Purge worker required'; END IF; PERFORM 1 FROM nexa.rev869b_purge_authorizations a JOIN nexa.rev869b_target_instance_identity i ON i."IdentityId" AND i."DatabaseName"=current_database() AND i."InstanceSha256"=a."TargetInstanceSha256" WHERE a."AuthorizationId"=authorization_id AND a."AuthorizedBatchId"=purge_attempt_id AND a."Operation"='CommandContextRetentionPurge' AND a."State"='Approved' AND a."ExpiresAt">clock_timestamp() FOR UPDATE OF a; IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='42501',CONSTRAINT='rev869b_purge_batch_binding',MESSAGE='Fresh authorization for this exact purge batch and authoritative target instance is unavailable'; END IF;
          SELECT substring("Scope" from 14) INTO STRICT approved_organization FROM nexa.rev869b_purge_authorizations WHERE "AuthorizationId"=authorization_id;
          INSERT INTO nexa.rev869b_purge_attempts("PurgeAttemptId","AuthorizationId","CandidateCount","CandidateSha256","State") VALUES(purge_attempt_id,authorization_id,0,digest('','sha256'),'Started');
          INSERT INTO nexa.rev869b_purge_candidates SELECT purge_attempt_id,'command_contexts',c."ContextToken" FROM nexa.rev869b_command_contexts c JOIN nexa.rev869b_command_attempts ca ON ca."AttemptId"=c."AttemptId" JOIN nexa.rev869b_command_requests cr ON cr."CommandId"=ca."CommandId" WHERE cr."OrganizationId"=approved_organization AND c."OpenedAt"<(SELECT "Cutoff" FROM nexa.rev869b_purge_authorizations WHERE "AuthorizationId"=authorization_id) ORDER BY c."ContextToken" LIMIT (SELECT "MaximumRows" FROM nexa.rev869b_purge_authorizations WHERE "AuthorizationId"=authorization_id); GET DIAGNOSTICS count_rows=ROW_COUNT;
          SELECT digest(coalesce(string_agg("LedgerName"||':'||"RowId"::text,',' ORDER BY "LedgerName","RowId"),''),'sha256') INTO candidate_sha FROM nexa.rev869b_purge_candidates WHERE "PurgeAttemptId"=purge_attempt_id;
          UPDATE nexa.rev869b_purge_attempts SET "CandidateCount"=count_rows,"CandidateSha256"=candidate_sha,"State"=CASE WHEN count_rows=0 THEN 'ZeroRows' ELSE 'Started' END,"TerminalAt"=CASE WHEN count_rows=0 THEN clock_timestamp() ELSE NULL END WHERE "PurgeAttemptId"=purge_attempt_id; UPDATE nexa.rev869b_purge_authorizations SET "State"=CASE WHEN count_rows=0 THEN 'ZeroRows' ELSE 'Started' END WHERE "AuthorizationId"=authorization_id; INSERT INTO nexa.rev869b_purge_events VALUES(DEFAULT,purge_attempt_id,CASE WHEN count_rows=0 THEN 'ZeroRows' ELSE 'Started' END,candidate_sha,clock_timestamp(),session_user); RETURN purge_attempt_id;
        END $f$;
        CREATE FUNCTION nexa.rev869b_execute_purge(purge_attempt_id uuid) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,nexa AS $f$ DECLARE expected integer; deleted integer; evidence bytea; BEGIN
          IF session_user<>'nexa_rev869b_purge_worker' THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Purge worker required'; END IF; SELECT "CandidateCount" INTO STRICT expected FROM nexa.rev869b_purge_attempts WHERE "PurgeAttemptId"=purge_attempt_id AND "State"='Started' FOR UPDATE;
          IF EXISTS(SELECT 1 FROM nexa.rev869b_purge_candidates p JOIN nexa.rev869b_command_contexts c ON c."ContextToken"=p."RowId" JOIN nexa.rev869b_command_attempts a ON a."AttemptId"=c."AttemptId" WHERE p."PurgeAttemptId"=purge_attempt_id AND a."IsActive") THEN RAISE EXCEPTION USING ERRCODE='40001',CONSTRAINT='rev869b_purge_candidate_drift',MESSAGE='Frozen candidates drifted'; END IF; DELETE FROM nexa.rev869b_command_claims q USING nexa.rev869b_purge_candidates p WHERE p."PurgeAttemptId"=purge_attempt_id AND p."LedgerName"='command_contexts' AND q."ContextToken"=p."RowId"; DELETE FROM nexa.rev869b_command_contexts c USING nexa.rev869b_purge_candidates p WHERE p."PurgeAttemptId"=purge_attempt_id AND p."LedgerName"='command_contexts' AND c."ContextToken"=p."RowId"; GET DIAGNOSTICS deleted=ROW_COUNT; IF deleted<>expected THEN RAISE EXCEPTION USING ERRCODE='40001',CONSTRAINT='rev869b_purge_candidate_drift',MESSAGE='Frozen candidates drifted'; END IF;
          evidence:=digest(purge_attempt_id::text||':'||deleted::text,'sha256'); UPDATE nexa.rev869b_purge_attempts SET "State"='Succeeded',"TerminalAt"=clock_timestamp() WHERE "PurgeAttemptId"=purge_attempt_id; UPDATE nexa.rev869b_purge_authorizations SET "State"='Succeeded' WHERE "AuthorizationId"=(SELECT "AuthorizationId" FROM nexa.rev869b_purge_attempts WHERE "PurgeAttemptId"=purge_attempt_id); INSERT INTO nexa.rev869b_purge_events VALUES(DEFAULT,purge_attempt_id,'Succeeded',evidence,clock_timestamp(),session_user); RETURN deleted;
        END $f$;
        CREATE FUNCTION nexa.rev869b_record_purge_failure(purge_attempt_id uuid,terminal_state text,category text,evidence bytea) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,nexa AS $f$ DECLARE existing nexa.rev869b_purge_events%ROWTYPE; existing_category text; BEGIN IF session_user<>'nexa_rev869b_purge_audit' OR terminal_state NOT IN ('Failed','Interrupted') OR length(category) NOT BETWEEN 1 AND 100 OR octet_length(evidence)<>32 THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Exact independent purge failure required'; END IF; SELECT * INTO existing FROM nexa.rev869b_purge_events e WHERE e."PurgeAttemptId"=purge_attempt_id AND e."State"=terminal_state; IF FOUND THEN SELECT p."FailureCategory" INTO STRICT existing_category FROM nexa.rev869b_purge_attempts p WHERE p."PurgeAttemptId"=purge_attempt_id; IF existing."EvidenceSha256"<>evidence OR existing."Principal"<>session_user OR existing_category<>category THEN RAISE EXCEPTION USING ERRCODE='23505',CONSTRAINT='rev869b_purge_failure_replay_mismatch',MESSAGE='Purge failure replay mismatch'; END IF; RETURN purge_attempt_id; END IF; UPDATE nexa.rev869b_purge_attempts SET "State"=terminal_state,"TerminalAt"=clock_timestamp(),"FailureCategory"=category WHERE "PurgeAttemptId"=purge_attempt_id AND "State"='Started'; IF NOT FOUND THEN RAISE EXCEPTION 'Purge attempt not Started'; END IF; UPDATE nexa.rev869b_purge_authorizations SET "State"=terminal_state WHERE "AuthorizationId"=(SELECT "AuthorizationId" FROM nexa.rev869b_purge_attempts WHERE "PurgeAttemptId"=purge_attempt_id); INSERT INTO nexa.rev869b_purge_events VALUES(DEFAULT,purge_attempt_id,terminal_state,evidence,clock_timestamp(),session_user); RETURN purge_attempt_id; END $f$;
        CREATE FUNCTION nexa.rev869b_reconcile_purge(purge_attempt_id uuid) RETURNS jsonb LANGUAGE sql SECURITY DEFINER STABLE SET search_path=pg_catalog,nexa AS $f$ SELECT to_jsonb(p) FROM nexa.rev869b_purge_attempts p WHERE p."PurgeAttemptId"=$1 AND session_user IN ('nexa_rev869b_purge_worker','nexa_rev869b_purge_audit','nexa_rev869b_target_verifier') $f$;

        CREATE FUNCTION nexa.rev869b_register_export_authorization(authorization_id uuid,decision_id uuid,organization text,fields text[],maximum_rows integer,as_of timestamptz,expires_at timestamptz) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,nexa AS $f$ DECLARE allowed text[]:=ARRAY['occurredAt','eventType','organizationId','attemptId']; BEGIN IF session_user<>'nexa_rev869b_management_writer' OR organization='' OR fields<@allowed IS NOT TRUE OR array_length(fields,1) IS NULL OR cardinality(fields)<>(SELECT count(DISTINCT value) FROM unnest(fields) value) OR as_of>clock_timestamp() THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Management-approved export allowlist required'; END IF; INSERT INTO nexa.rev869b_export_authorizations("AuthorizationId","ManagementDecisionId","OrganizationId","Fields","MaximumRows","AsOf","ExpiresAt") VALUES(authorization_id,decision_id,organization,fields,maximum_rows,as_of,expires_at); RETURN authorization_id; END $f$;
        CREATE FUNCTION nexa.rev869b_prepare_export_batch(batch_id uuid,authorization_id uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,nexa AS $f$ DECLARE a nexa.rev869b_export_authorizations%ROWTYPE; rows_count integer; batch_sha bytea; BEGIN
          IF session_user<>'nexa_rev869b_export_service' THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Controlled export service required'; END IF; SELECT * INTO STRICT a FROM nexa.rev869b_export_authorizations WHERE "AuthorizationId"=authorization_id AND "State"='Approved' AND "ExpiresAt">clock_timestamp() FOR UPDATE;
          INSERT INTO nexa.rev869b_export_batches VALUES(batch_id,authorization_id,a."ManagementDecisionId",a."OrganizationId",a."Fields",a."MaximumRows",a."AsOf",a."ExpiresAt",0,digest('','sha256'),clock_timestamp()); INSERT INTO nexa.rev869b_export_batch_rows SELECT batch_id,row_number() OVER(ORDER BY o."OccurredAt",o."OutcomeId")::integer,minimized.payload,digest(minimized.payload::text,'sha256') FROM nexa.rev869b_command_attempt_outcomes o JOIN nexa.rev869b_command_attempts a2 ON a2."AttemptId"=o."AttemptId" JOIN nexa.rev869b_command_requests r ON r."CommandId"=a2."CommandId" CROSS JOIN LATERAL (SELECT coalesce(jsonb_object_agg(field.key,field.value),'{}'::jsonb) payload FROM jsonb_each(jsonb_strip_nulls(jsonb_build_object('occurredAt',o."OccurredAt",'eventType',o."TerminalState",'organizationId',r."OrganizationId",'attemptId',o."AttemptId"))) field WHERE field.key=ANY(a."Fields")) minimized WHERE r."OrganizationId"=a."OrganizationId" AND o."OccurredAt"<=a."AsOf" ORDER BY o."OccurredAt",o."OutcomeId" LIMIT a."MaximumRows";
          GET DIAGNOSTICS rows_count=ROW_COUNT; SELECT digest(coalesce(string_agg(encode("RowSha256",'hex'),',' ORDER BY "Ordinal"),''),'sha256') INTO batch_sha FROM nexa.rev869b_export_batch_rows WHERE "BatchId"=batch_id; UPDATE nexa.rev869b_export_batches SET "RowCount"=rows_count,"BatchSha256"=batch_sha WHERE "BatchId"=batch_id; UPDATE nexa.rev869b_export_authorizations SET "State"='Prepared' WHERE "AuthorizationId"=authorization_id; RETURN batch_id;
        END $f$;
        CREATE FUNCTION nexa.rev869b_authorize_export_release(batch_id uuid,release_id uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,nexa AS $f$ BEGIN IF session_user<>'nexa_rev869b_export_service' OR NOT EXISTS(SELECT 1 FROM nexa.rev869b_export_batches WHERE "BatchId"=batch_id AND "ExpiresAt">clock_timestamp()) OR EXISTS(SELECT 1 FROM nexa.rev869b_export_releases WHERE "BatchId"=batch_id AND "State" NOT IN ('Failed','Interrupted')) THEN RAISE EXCEPTION USING ERRCODE='42501',CONSTRAINT='rev869b_export_release_sequence',MESSAGE='Prepared unexpired retry-eligible batch required'; END IF; INSERT INTO nexa.rev869b_export_releases VALUES(release_id,batch_id,'ReleaseStarted',clock_timestamp(),NULL,NULL); RETURN release_id; END $f$;
        CREATE FUNCTION nexa.rev869b_read_prepared_export_batch(batch_id uuid,release_id uuid) RETURNS TABLE(ordinal integer,payload jsonb,row_sha256 bytea) LANGUAGE sql SECURITY DEFINER STABLE SET search_path=pg_catalog,nexa AS $f$ SELECT r."Ordinal",r."Payload",r."RowSha256" FROM nexa.rev869b_export_batch_rows r JOIN nexa.rev869b_export_releases x ON x."BatchId"=r."BatchId" JOIN nexa.rev869b_export_batches b ON b."BatchId"=r."BatchId" WHERE r."BatchId"=$1 AND x."ReleaseId"=$2 AND x."State"='ReleaseStarted' AND b."ExpiresAt">clock_timestamp() AND session_user='nexa_rev869b_export_service' ORDER BY r."Ordinal" $f$;
        CREATE FUNCTION nexa.rev869b_record_export_release_outcome(release_id uuid,terminal_state text,category text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,nexa AS $f$ BEGIN IF session_user<>'nexa_rev869b_export_service' OR terminal_state NOT IN ('Delivered','Failed','Interrupted') OR (terminal_state='Delivered' AND category IS NOT NULL) OR (terminal_state<>'Delivered' AND length(category) NOT BETWEEN 1 AND 100) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Exact release outcome required'; END IF; UPDATE nexa.rev869b_export_releases SET "State"=terminal_state,"TerminalAt"=clock_timestamp(),"OutcomeCategory"=category WHERE "ReleaseId"=release_id AND "State"='ReleaseStarted'; IF NOT FOUND THEN RAISE EXCEPTION 'Release missing or terminal'; END IF; RETURN release_id; END $f$;

        CREATE FUNCTION nexa.rev869b_verify_target_catalogue_acl() RETURNS text LANGUAGE plpgsql SECURITY DEFINER STABLE SET search_path=pg_catalog,nexa AS $f$ DECLARE mismatch boolean; BEGIN
          IF session_user<>'nexa_rev869b_target_verifier' THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Target verifier required'; END IF;
          IF (SELECT "CatalogueSha256"<>nexa.rev869b_target_catalogue_fingerprint() FROM nexa.rev869b_target_catalogue_manifest) IS DISTINCT FROM false THEN RAISE EXCEPTION 'Target catalogue fingerprint mismatch'; END IF;
          WITH expected(role_name,signature) AS (VALUES
            ('nexa_rev869b_app_runtime','nexa.rev869b_open_command_attempt(uuid,uuid,text,text,text,text,bytea,jsonb)'),('nexa_rev869b_app_runtime','nexa.rev869b_command_context_valid(text,uuid,text,text,text)'),('nexa_rev869b_app_runtime','nexa.rev869b_claim_command_context(text,uuid,text,uuid,text,bigint,text,text,text,text)'),('nexa_rev869b_app_runtime','nexa.rev869b_commit_command_attempt(uuid,bytea,jsonb,uuid)'),
            ('nexa_rev869b_command_audit','nexa.rev869b_register_command_request(text,text,bytea,bytea,uuid,text,text,text)'),('nexa_rev869b_command_audit','nexa.rev869b_start_command_attempt(uuid,uuid,bytea,bytea,name,integer,bigint)'),('nexa_rev869b_command_audit','nexa.rev869b_record_noncommit_outcome(uuid,uuid,bytea,bytea,text,text,uuid)'),('nexa_rev869b_command_audit','nexa.rev869b_reconcile_command_attempt(uuid)'),
            ('nexa_rev869b_management_writer','nexa.rev869b_register_purge_authorization(uuid,uuid,uuid,uuid,uuid,bytea,text,text,timestamp with time zone,integer,bytea,text,bytea,timestamp with time zone)'),('nexa_rev869b_management_writer','nexa.rev869b_register_export_authorization(uuid,uuid,text,text[],integer,timestamp with time zone,timestamp with time zone)'),
            ('nexa_rev869b_purge_worker','nexa.rev869b_start_purge(uuid,uuid)'),('nexa_rev869b_purge_worker','nexa.rev869b_execute_purge(uuid)'),('nexa_rev869b_purge_worker','nexa.rev869b_reconcile_purge(uuid)'),
            ('nexa_rev869b_purge_audit','nexa.rev869b_record_purge_failure(uuid,text,text,bytea)'),('nexa_rev869b_purge_audit','nexa.rev869b_reconcile_purge(uuid)'),
            ('nexa_rev869b_export_service','nexa.rev869b_prepare_export_batch(uuid,uuid)'),('nexa_rev869b_export_service','nexa.rev869b_authorize_export_release(uuid,uuid)'),('nexa_rev869b_export_service','nexa.rev869b_read_prepared_export_batch(uuid,uuid)'),('nexa_rev869b_export_service','nexa.rev869b_record_export_release_outcome(uuid,text,text)'),
            ('nexa_rev869b_target_verifier','nexa.rev869b_reconcile_command_attempt(uuid)'),('nexa_rev869b_target_verifier','nexa.rev869b_reconcile_purge(uuid)'),('nexa_rev869b_target_verifier','nexa.rev869b_read_target_security_state()'),('nexa_rev869b_target_verifier','nexa.rev869b_read_command_evidence(uuid,uuid)'),('nexa_rev869b_target_verifier','nexa.rev869b_read_purge_evidence(uuid,uuid)'),('nexa_rev869b_target_verifier','nexa.rev869b_read_export_evidence(uuid,uuid,uuid)'),('nexa_rev869b_target_verifier','nexa.rev869b_read_target_acl_evidence()'),('nexa_rev869b_target_verifier','nexa.rev869b_read_command_evidence_v2(bytea,uuid,text,text,uuid,uuid)'),('nexa_rev869b_target_verifier','nexa.rev869b_read_purge_evidence_v2(bytea,uuid,text,text,uuid,uuid,uuid,uuid)'),('nexa_rev869b_target_verifier','nexa.rev869b_read_export_evidence_v2(bytea,uuid,text,text,uuid,uuid,uuid,timestamp with time zone)'),('nexa_rev869b_target_verifier','nexa.rev869b_read_target_acl_evidence_v2(bytea,uuid,text,text,name,text,text,text)'),('nexa_rev869b_target_verifier','nexa.rev869b_read_command_facts_v3(text,bytea,uuid,bigint,uuid,uuid,uuid,text,text[])'),('nexa_rev869b_target_verifier','nexa.rev869b_read_purge_facts_v3(text,bytea,uuid,bigint,uuid,uuid,uuid,uuid,uuid,uuid,text,text[])'),('nexa_rev869b_target_verifier','nexa.rev869b_read_export_facts_v3(text,bytea,uuid,bigint,uuid,uuid,uuid,timestamp with time zone,uuid,text,uuid,text[])'),('nexa_rev869b_target_verifier','nexa.rev869b_read_target_acl_facts_v3(text,bytea,uuid,bigint,uuid,uuid,name,text,text,text,text[])'),('nexa_rev869b_target_verifier','nexa.rev869b_target_catalogue_fingerprint()'),('nexa_rev869b_target_verifier','nexa.rev869b_verify_target_catalogue_acl()')),
          actual AS (SELECT r.rolname::text role_name,p.oid::regprocedure::text signature FROM pg_roles r CROSS JOIN pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='nexa' AND NOT r.rolsuper AND r.rolname!~'^pg_' AND r.rolname<>'nexa_rev869b_security_owner' AND has_function_privilege(r.oid,p.oid,'EXECUTE')),
          delta AS ((SELECT * FROM expected EXCEPT SELECT * FROM actual) UNION ALL (SELECT * FROM actual EXCEPT SELECT * FROM expected)) SELECT EXISTS(SELECT 1 FROM delta) INTO mismatch;
          IF mismatch THEN RAISE EXCEPTION 'Target function ACL mismatch'; END IF;
          WITH read_relation(relation_name) AS (VALUES
            ('employees'),('employee_identity_mappings'),('employee_role_assignments'),('employee_operational_scopes'),('roles'),('role_page_permissions'),('page_definitions'),('items'),('uoms'),('uom_conversions'),('vendors'),('tax_gst_settings'),('organization_policies'),('warehouses'),('purchase_requisitions'),('purchase_requisition_lines'),('purchase_requirement_handoffs'),('purchase_approval_route_settings'),('purchase_approval_workflow_steps'),('purchase_transaction_approval_policies')),
          write_relation(relation_name) AS (VALUES
            ('vendor_qualifications'),('controlled_configuration_histories'),('request_for_quotations'),('request_for_quotation_lines'),('rfq_vendor_invitations'),('vendor_quotations'),('vendor_quotation_lines'),('quotation_technical_verifications'),('commercial_comparisons'),('commercial_comparison_lines'),('purchase_transaction_status_history'),('purchase_transaction_approval_history'),('purchase_orders'),('purchase_order_lines'),('purchase_order_history'),('material_followup_handoffs'),('purchase_number_sequences')),
          expected(role_name,relation_name,privilege_name) AS (
            SELECT 'nexa_rev869b_app_runtime',relation_name,'SELECT' FROM read_relation
            UNION ALL SELECT 'nexa_rev869b_app_runtime',relation_name,p FROM write_relation CROSS JOIN unnest(ARRAY['SELECT','INSERT','UPDATE']) p
            UNION ALL SELECT 'nexa_rev869b_app_runtime','audit_logs',p FROM unnest(ARRAY['SELECT','INSERT']) p),
          checked_role(role_name) AS (SELECT rolname::text FROM pg_roles WHERE NOT rolsuper AND rolname!~'^pg_' AND rolname<>'nexa_rev869b_security_owner'),
          checked_privilege(privilege_name) AS (VALUES ('SELECT'),('INSERT'),('UPDATE'),('DELETE'),('TRUNCATE'),('REFERENCES'),('TRIGGER')),
          actual AS (SELECT r.role_name,c.relname::text relation_name,p.privilege_name FROM checked_role r CROSS JOIN pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace CROSS JOIN checked_privilege p WHERE n.nspname='nexa' AND c.relkind IN ('r','p','v','m','f') AND has_table_privilege(r.role_name,c.oid,p.privilege_name)),
          delta AS ((SELECT * FROM expected EXCEPT SELECT * FROM actual) UNION ALL (SELECT * FROM actual EXCEPT SELECT * FROM expected)) SELECT EXISTS(SELECT 1 FROM delta) INTO mismatch;
          IF mismatch OR EXISTS(SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='nexa' AND c.relkind IN ('r','p','v','m','f') AND has_table_privilege('public',c.oid,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER')) THEN RAISE EXCEPTION 'Target relation ACL mismatch'; END IF;
          IF EXISTS(SELECT 1 FROM pg_roles r CROSS JOIN pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='nexa' AND c.relkind='S' AND NOT r.rolsuper AND r.rolname!~'^pg_' AND r.rolname<>'nexa_rev869b_security_owner' AND has_sequence_privilege(r.oid,c.oid,'SELECT,UPDATE,USAGE')) OR EXISTS(SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='nexa' AND c.relkind='S' AND has_sequence_privilege('public',c.oid,'SELECT,UPDATE,USAGE')) THEN RAISE EXCEPTION 'Target sequence ACL mismatch'; END IF;
          IF EXISTS(SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='nexa' AND c.relkind IN ('r','p','S','v','m','f') AND pg_get_userbyid(c.relowner)<>'nexa_rev869b_security_owner') OR EXISTS(SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='nexa' AND pg_get_userbyid(p.proowner)<>'nexa_rev869b_security_owner') THEN RAISE EXCEPTION 'Target object ownership mismatch'; END IF;
          IF EXISTS(SELECT 1 FROM pg_default_acl d CROSS JOIN LATERAL aclexplode(d.defaclacl) x WHERE d.defaclnamespace='nexa'::regnamespace AND (x.grantee=0 OR x.grantee<>d.defaclrole)) THEN RAISE EXCEPTION 'Target default ACL mismatch'; END IF;
          IF EXISTS(SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace CROSS JOIN LATERAL aclexplode(c.relacl) x JOIN pg_roles r ON r.oid=x.grantee WHERE n.nspname='nexa' AND r.rolname~'^pg_' UNION ALL SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace CROSS JOIN LATERAL aclexplode(p.proacl) x JOIN pg_roles r ON r.oid=x.grantee WHERE n.nspname='nexa' AND r.rolname~'^pg_' UNION ALL SELECT 1 FROM pg_namespace n CROSS JOIN LATERAL aclexplode(n.nspacl) x JOIN pg_roles r ON r.oid=x.grantee WHERE n.nspname='nexa' AND r.rolname~'^pg_' UNION ALL SELECT 1 FROM pg_database d CROSS JOIN LATERAL aclexplode(d.datacl) x JOIN pg_roles r ON r.oid=x.grantee WHERE d.datname=current_database() AND r.rolname~'^pg_' UNION ALL SELECT 1 FROM pg_default_acl d CROSS JOIN LATERAL aclexplode(d.defaclacl) x JOIN pg_roles r ON r.oid=x.grantee WHERE d.defaclnamespace='nexa'::regnamespace AND r.rolname~'^pg_') THEN RAISE EXCEPTION 'Target predefined role direct ACL mismatch'; END IF;
          IF EXISTS(SELECT 1 FROM pg_auth_members m JOIN pg_roles a ON a.oid=m.roleid JOIN pg_roles b ON b.oid=m.member WHERE (a.rolname LIKE 'nexa_rev869b_%' OR b.rolname LIKE 'nexa_rev869b_%') AND NOT (a.rolname='nexa_rev869b_security_owner' AND b.rolname='nexa_rev869b_lifecycle_administrator')) OR NOT EXISTS(SELECT 1 FROM pg_auth_members m JOIN pg_roles a ON a.oid=m.roleid JOIN pg_roles b ON b.oid=m.member WHERE a.rolname='nexa_rev869b_security_owner' AND b.rolname='nexa_rev869b_lifecycle_administrator') THEN RAISE EXCEPTION 'Target role membership mismatch'; END IF;
          IF EXISTS(SELECT 1 FROM pg_roles r WHERE NOT r.rolsuper AND r.rolname!~'^pg_' AND r.rolname NOT IN ('nexa_rev869b_security_owner','nexa_rev869b_lifecycle_administrator','nexa_rev869b_app_runtime','nexa_rev869b_command_audit','nexa_rev869b_management_writer','nexa_rev869b_purge_worker','nexa_rev869b_purge_audit','nexa_rev869b_export_service','nexa_rev869b_target_verifier') AND has_database_privilege(r.oid,current_database(),'CONNECT,TEMPORARY')) OR EXISTS(SELECT 1 FROM pg_roles r WHERE r.rolname IN ('nexa_rev869b_lifecycle_administrator','nexa_rev869b_app_runtime','nexa_rev869b_command_audit','nexa_rev869b_management_writer','nexa_rev869b_purge_worker','nexa_rev869b_purge_audit','nexa_rev869b_export_service','nexa_rev869b_target_verifier') AND (NOT has_database_privilege(r.oid,current_database(),'CONNECT') OR has_database_privilege(r.oid,current_database(),'TEMPORARY'))) THEN RAISE EXCEPTION 'Target database ACL mismatch'; END IF;
          IF EXISTS(SELECT 1 FROM pg_roles r WHERE NOT r.rolsuper AND r.rolname!~'^pg_' AND r.rolname<>'nexa_rev869b_security_owner' AND (has_schema_privilege(r.oid,'nexa','CREATE') OR has_schema_privilege(r.oid,'nexa','USAGE') IS DISTINCT FROM (r.rolname IN ('nexa_rev869b_app_runtime','nexa_rev869b_command_audit','nexa_rev869b_management_writer','nexa_rev869b_purge_worker','nexa_rev869b_purge_audit','nexa_rev869b_export_service','nexa_rev869b_target_verifier')))) THEN RAISE EXCEPTION 'Target schema ACL mismatch'; END IF;
          IF pg_get_userbyid((SELECT nspowner FROM pg_namespace WHERE nspname='nexa'))<>'nexa_rev869b_security_owner' THEN RAISE EXCEPTION 'Target schema owner mismatch'; END IF;
          IF pg_get_userbyid((SELECT datdba FROM pg_database WHERE datname=current_database()))<>'nexa_rev869b_security_owner' THEN RAISE EXCEPTION 'Target database owner mismatch'; END IF;
          IF EXISTS(SELECT 1 FROM pg_roles r WHERE r.rolname IN ('nexa_rev869b_security_owner','nexa_rev869b_lifecycle_administrator','nexa_rev869b_app_runtime','nexa_rev869b_command_audit','nexa_rev869b_management_writer','nexa_rev869b_purge_worker','nexa_rev869b_purge_audit','nexa_rev869b_export_service','nexa_rev869b_target_verifier') AND (r.rolsuper OR r.rolcreatedb OR r.rolcreaterole OR r.rolreplication OR r.rolbypassrls OR r.rolinherit OR (r.rolname='nexa_rev869b_security_owner' AND r.rolcanlogin) OR (r.rolname<>'nexa_rev869b_security_owner' AND NOT r.rolcanlogin))) THEN RAISE EXCEPTION 'Target role capability mismatch'; END IF;
          RETURN 'REV869B_TARGET_CATALOGUE_ACL_EXACT'; END $f$;

        DO $ownership$ DECLARE o regclass; f regprocedure; BEGIN
          FOR o IN SELECT c.oid::regclass FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='nexa' AND c.relkind IN ('r','p') LOOP EXECUTE format('ALTER TABLE %s OWNER TO nexa_rev869b_security_owner',o); END LOOP;
          FOR o IN SELECT c.oid::regclass FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='nexa' AND c.relkind='S' LOOP EXECUTE format('ALTER SEQUENCE %s OWNER TO nexa_rev869b_security_owner',o); END LOOP;
          FOR o IN SELECT c.oid::regclass FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='nexa' AND c.relkind='v' LOOP EXECUTE format('ALTER VIEW %s OWNER TO nexa_rev869b_security_owner',o); END LOOP;
          FOR o IN SELECT c.oid::regclass FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='nexa' AND c.relkind='m' LOOP EXECUTE format('ALTER MATERIALIZED VIEW %s OWNER TO nexa_rev869b_security_owner',o); END LOOP;
          FOR o IN SELECT c.oid::regclass FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='nexa' AND c.relkind='f' LOOP EXECUTE format('ALTER FOREIGN TABLE %s OWNER TO nexa_rev869b_security_owner',o); END LOOP;
          FOR f IN SELECT p.oid::regprocedure FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='nexa' LOOP EXECUTE format('ALTER FUNCTION %s OWNER TO nexa_rev869b_security_owner',f); END LOOP;
          ALTER SCHEMA nexa OWNER TO nexa_rev869b_security_owner;
        END $ownership$;
        REVOKE ALL ON ALL TABLES IN SCHEMA nexa FROM PUBLIC,nexa_rev869b_app_runtime,nexa_rev869b_command_audit,nexa_rev869b_management_writer,nexa_rev869b_purge_worker,nexa_rev869b_purge_audit,nexa_rev869b_export_service,nexa_rev869b_target_verifier;
        REVOKE ALL ON ALL SEQUENCES IN SCHEMA nexa FROM PUBLIC,nexa_rev869b_app_runtime,nexa_rev869b_command_audit,nexa_rev869b_management_writer,nexa_rev869b_purge_worker,nexa_rev869b_purge_audit,nexa_rev869b_export_service,nexa_rev869b_target_verifier;
